INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(4, 'O mne', 'o-mne', '[hlavicka typ=\"hero_banner\" title=\"Příroda je nejlepší učebna\" text=\"Výlety I Expedice I Vzdělávací kurzy I Kroužky\" img=\"/img/slidelod.jpg\" overlay=\"0.3\"]\r\n\r\n\r\n[blok typ=\"blok_nadpis4\" nadpis=\"Něco málo o mne\" text=\" Jsem zkušený cestovatel a průvodce dětí. Rozumím respektující výchově dětí, mám nápady jak udělat\r\n                    dětem ze života radost a příležitost k seberozvoji.\"]\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom rounded-4 mx-2 mx-lg-4 my-4 shadow-sm\">\r\n    <div class=\"container py-4\">\r\n        <div class=\"row flex-lg-row-reverse align-items-center g-5\">\r\n\r\n            <div class=\"col-12 col-lg-6 text-center\">\r\n                <div\r\n                    class=\"position-relative p-2 bg-white rounded-4 shadow-sm border border-info border-opacity-10 d-inline-block\">\r\n                    <img src=\"/img/ja4.jpg\" class=\"img-fluid rounded-4 shadow-sm\" alt=\"Petr Lízal\" loading=\"lazy\"\r\n                        style=\"object-fit: cover; max-width: 100%;\">\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-12 col-lg-6 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Můj příběh\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                <h4 class=\"display-6 fw-bold text-dark mb-4\" style=\"line-height: 1.2;\">Něco málo o mně</h4>\r\n\r\n                <div>\r\n                    <p class=\"fw-light mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo\r\n                        odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do\r\n                        neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam\r\n                        se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek,\r\n                        stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti.\r\n                        Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let\r\n                        předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace,\r\n                        Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad\r\n                        sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Nejdůležitější je pro mě atmosféra — místo, kde děti mohou být\r\n                        samy sebou, svobodně objevovat svět a cítit, že jsou přijímány takové, jaké jsou.</p>\r\n\r\n                    <p class=\"fw-light mb-0\">Na Svobodomě vytvářím právě takový prostor. Bez nátlaku, bez\r\n                        manipulace a bez plánů narýsovaných shora. Jen s respektem, důvěrou a lidskostí.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center\">\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-gears fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Svoboda a zodpovědnost</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Jsem přesvědčen, že si každý o svém životě dokáže nejlépe rozhodovat sám. Všechny svobodné děti\r\n                        se rády učí už od přírody, není je potřeba nutit a brát jim jejich zodpovědnost za svůj život.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-people-arrows fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respekt, účel nesvětí prostředky</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Považuji za správné nikoho k ničemu násilím nenutit, dokud si dotyčný hledí svého a nijak útokem\r\n                        neubližuje druhým; a ani když si zásah vůči němu většina demokraticky odhlasuje, neudělá to ze\r\n                        zlé věci dobrou.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-arrows-alt fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dobrovolnost a volba</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Rozumím respektující výchově, ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a\r\n                        potřeb, následně společně tvoříme přijatelná řešení.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-5 justify-content-center\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Kamarádi </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-campground text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dobrodružství </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-tree text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Pobyt v přírodě </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-compass text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dovednosti </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-handshake text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Respekt </h5>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-4 text-center\">\r\n        <h1 class=\"display-6 fw-bold text-dark mb-3\">Zaplatit profesionála se vyplatí</h1>\r\n        <div class=\"row justify-content-center mb-5\">\r\n            <div class=\"col-12 col-md-8 col-lg-6\">\r\n                <p class=\"lead mb-0\">Nabízím na prvním místě bezpečné motivující prostředí.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-left-right fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">„Průvodci jsou pro děti partneři, ne diktátoři“</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Výjimečnost <i class=\"fa-solid fa-fire text-info mx-1\"></i><span\r\n                            class=\"text-info fw-bold\">dobrodruzi.cz</span> spočívá ve spolupráci s profesionálními\r\n                        průvodci, kteří jsou nejen zkušenými cestovateli, ale rozumí i respektující výchově. Právě to je\r\n                        velká výhoda oproti jiným dobrovolnickým organizacím, protože v nich často působí mladí lidé,\r\n                        kteří nemají dostatečné znalosti a zkušenosti. Né nadarmo se říká, levné věci jsou drahé.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-holding-heart fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Dvacet let jako dobrovolník</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Věnoval jsem dětem již tisíce hodin a statisíce korun ze své kapsy. Jako každý člověk mám ve\r\n                        svém životě <strong>omezený zdroj času, rád daruji část svého</strong>, přesto další část musím\r\n                        investovat do práce která mě uživí.​ Nabízím dětem placené kurzy, výlety, kroužky, je to práce\r\n                        jako každá jiná.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light text-black rounded-4 my-4 text-center\">\r\n    <div class=\"container py-4\">\r\n        <h1 class=\"display-5 fw-bold text-black mb-4\">Směna je užitečná</h1>\r\n        <div class=\"row justify-content-center\">\r\n            <div class=\"col-12 col-md-10 col-lg-8\">\r\n                <p class=\"lead mb-5\">\r\n                    Už od počátku věků si lidé vyměňují užitečné služby skrze peníze, zkrátka protože je to <strong>pro\r\n                        obě strany výhodné</strong> a mají z toho <strong>užitek</strong>.\r\n                </p>\r\n                <div class=\"d-grid gap-2 d-sm-flex justify-content-sm-center\">\r\n                    <a class=\"btn btn-info text-dark fw-bold btn-lg px-4 rounded-3 shadow-sm\"\r\n                        href=\"https://dobrodruzi.cz/rezervace/\">\r\n                        Objednat průvodce\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Nabízím profesionální služby pro děti</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Velkým dobrodruhům pomáhám uskutečnit náročné expedice, naopak mladším rád uspořádám dobrodružný\r\n                        výlet na míru. V nabídce mám nejrůznější kurzy, během roku pořádám různorodé kroužky.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-sparkles fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Tvořím pro děti příležitosti k osobnímu rozvoji</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Činnost pro děti tvořím tam, kde je o to zájem, proto mne neváhejte kontaktovat. Mohu stvořit\r\n                        kroužek pro Vaše mladé dobrodruhy <strong>i v místě Vašeho bydliště</strong>.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>', 1, '2025-04-02 04:46:24', '2026-06-13 13:36:50'),
(6, 'Sebeřízené vzdělávání', 'homex', '[]', 1, '2025-04-02 04:52:32', '2025-09-05 15:17:51'),
(12, 'Nabízím', 'nabizim', '<p>Kurzy, kroužky, výlety</p>', 1, '2025-04-03 04:27:35', '2025-04-03 17:20:17'),
(13, 'Kurzy programování', 'kurzy-programovani', '[hlavicka typ=\"hero_sedy\" icon=\"fa-solid fa-laptop-code\" title=\"Soukromé kurzy programování\" text=\"Děti učím programovat, vytváříme počítačové hry, a trávíme čas ve zdravém prostředí.\"]\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-lg-3\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-xl-5 shadow-sm\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm mb-4\" style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-chalkboard-user fs-3\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Děti provedu IT světem</h4>\r\n                    <p class=\"fw-light lh-base \">Na kurzech děti učím základy programování a vytvářet jednoduché 2D hry.</p>\r\n                    <p class=\"fw-light lh-base\">Každému účastníkovi na lekci <strong class=\"text-dark\">zapůjčím notebook</strong>, je možné používat i vlastní zařízení.</p>\r\n                    <p class=\"fw-light lh-base  mb-0\">Kurzy mohou probíhat v místě vašeho bydliště, venku, v lese, v klubovně, u vás doma, v kavárnách, na veřejných místech.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-xl-5 shadow-sm\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm mb-4\" style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-tools fs-3\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Použijeme silný nástroj</h4>\r\n                    <p class=\"fw-light lh-base \">Pro vývoj her použijeme engin / software <a href=\"https://gamemaker.io/en\" target=\"_blank\" rel=\"noopener\" class=\"text-info text-decoration-none fw-medium\">Game Maker Studio 2</a>, to je vývojové prostředí které poskytuje silné nástroje pro začátečníky. Velká studia používají podobný engin jako je Unreal či Unity.</p>\r\n                    <p class=\"fw-light lh-base  mb-0\">V Game Makeru se používá vysokoúrovňový programovací jazyk zvaný GML, který je podobný například Javascriptu či Pythonu.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-xl-5 shadow-sm\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm mb-4\" style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-life-ring fs-3\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Pomohu v těžkých začátcích</h4>\r\n                    <p class=\"fw-light lh-base \">Vysvětlím jak fungují podmínky a cykly - for a while. Ukáži jak používat funkce a jak vytvářet vlastní. Neobejdeme se bez proměnných a polí.</p>\r\n                    <p class=\"fw-light lh-base  mb-0\">Pomohu a poradím, přesto děti budou muset překonávat překážky, samostatně zkoumat, trpělivě zkoušet, hledat neustále chyby. Na většinu věcí mohou přicházet i samostatně podle dokumentace.</p>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-6\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-laptop-code text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kurz</h5>\r\n                    <p class=\"fw-light small  mb-0\">pro jednoho účastníka</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-thumbs-up text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Věk</h5>\r\n                    <p class=\"fw-light small  mb-0\">od 8 do 15 let</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-hand-holding-heart text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Cena</h5>\r\n                    <p class=\"fw-light small  mb-0\">1 os. / měsíc / 2000 Kč</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-user-clock text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Délka lekce</h5>\r\n                    <p class=\"fw-light small  mb-0\">2 hodiny jednou týdně</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-calendar-days text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kdy</h5>\r\n                    <p class=\"fw-light small mb-0\">\r\n                        <a href=\"https://dobrodruzi.cz/index.php?page=6\" target=\"_blank\" rel=\"noopener\" class=\"text-info text-decoration-none fw-medium\">volné termíny</a>\r\n                    </p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-motorcycle text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kde</h5>\r\n                    <p class=\"fw-light small  mb-0\">Jindřichovice pod Smrkem <br>\r\n                        <a href=\"https://goo.gl/maps/itTNU4573LkMN6Jj7\" target=\"_blank\" rel=\"noopener\" class=\"text-info text-decoration-none fw-medium\">(mapa)</a>\r\n                    </p>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-sm-2 row-cols-md-3\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/pc4.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/pc6.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/pc2.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>', 1, '2025-04-03 17:22:45', '2026-06-12 20:55:46'),
(14, 'Výlet na míru', 'vylety', '<div class=\"container px-4 mt-5 pt-5 text-center\">\r\n    <h1 class=\"display-5 fw-bold text-dark mb-3\">Připravím výlet na míru</h1>\r\n    <div class=\"col-lg-7 mx-auto\">\r\n        <p class=\"lead mb-4\">Nabízím dětem zážitky a příležitosti k osobnímu rozvoji</p>\r\n    </div>\r\n</div>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container col-xxl-10 px-4\">\r\n        <div class=\"row align-items-center g-5 py-3\">\r\n            \r\n            <div class=\"col-12 col-lg-6 text-start\">\r\n                <h2 class=\"fw-bold lh-1 mb-4 text-dark display-6\">Mladé dobrodruhy učím základním cestovatelským dovednostem</h2>\r\n                <p class=\"lead mb-4\">Při cestování, získávají praktické dovednosti: jak číst v jízdních řádech a hledat spoje nebo jak se orientovat podle mapy, ať už jsme ve městě či v lese.</p>\r\n                <p class=\"lead mb-4\">Učíme se i tábornickým dovednostem, jak se ochránit před deštěm a proti prochladnutí, jak postavit stan, jak rozdělat oheň a uvařit si jídlo.​​​</p>\r\n                <a class=\"btn btn-info text-white btn-lg px-5 py-3 rounded-pill fw-bold shadow-sm mt-3\" href=\"https://dobrodruzi.cz/cs/stranka/kontakt\">Objednat soukromou akci​ »</a>\r\n            </div>\r\n            \r\n            <div class=\"col-12 col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10\">\r\n                    <img class=\"d-block mx-lg-auto img-fluid rounded-4 w-100\" style=\"object-fit: cover; min-height: 400px;\" src=\"/img/vylet2.jpg\" alt=\"popis\" loading=\"lazy\">\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-6\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kurz cestování</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">pro 1 až 6 účastníků</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-thumbs-up text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Věk</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">od 4 do 15 let</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-hand-holding-heart text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Cena</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">1500 Kč / 1 den / 1 až 6 os.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-user-clock text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Délka kurzu</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">1 až 4 dny</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-calendar-days text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kdy</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">kdykoli dle domluvy</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-map-location-dot text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kde</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">Liberec a okolí, ČR</p>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<div class=\"container px-4 mt-5 pt-4 text-center\">\r\n    <h2 class=\"display-6 fw-bold text-dark mb-3\">S profesionálním průvodcem budou mít pomocnou ruku</h2>\r\n    <div class=\"col-lg-8 mx-auto\">\r\n        <p class=\"lead mb-4\">Provázím mladé dobrodruhy na cestách za poznáním, a zajišťuji bezpečné putování</p>\r\n    </div>\r\n</div>\r\n\r\n<section class=\"py-4 bg-white\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-sm-2 row-cols-md-3\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/b8.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/b20.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/b19.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 mb-4 bg-white\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-lg-3\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-xl-5 shadow-sm text-center\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm mb-4 mx-auto\" style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-calendar-days fs-2\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">KDY</h5>\r\n                    <p class=\"fw-light mb-0\">Na výlet či na expedici (průzkumnou výpravu do neprobádaných končin světa) vyrážíme o víkendech nebo v expedičních termínech podle domluvy.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-xl-5 shadow-sm text-center\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm mb-4 mx-auto\" style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-people-arrows fs-2\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">KDE</h5>\r\n                    <p class=\"fw-light mb-0\">Scházíme se v Liberci na hlavním vlakovém nádraží, odtud vyrážíme na výlety po celé České republice. Účastníci si mohou zvolit i jiné místo pro sraz, záleží na přihlášených účastnících.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-xl-5 shadow-sm text-center\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm mb-4 mx-auto\" style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-arrows-up-down-left-right fs-2\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">PLÁN</h5>\r\n                    <p class=\"fw-light mb-0\">Cíle jednodenních i vícedenních výletů plánujeme podle zájmu dětí a tak, aby nebyly příliš finančně náročné, proto naše dobrodružná parta cestuje nejčastěji po České republice.</p>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>', 1, '2025-04-03 17:30:56', '2026-06-12 20:54:12'),
(15, 'Vodácký výlet', 'vodacky-vylet', '<div class=\"container px-4 mt-5 pt-5 text-center\">\r\n    <h1 class=\"display-5 fw-bold text-dark mb-3\">Dobrodružství na vodě</h1>\r\n    <div class=\"col-lg-6 mx-auto\">\r\n        <p class=\"lead mb-4\">Kurz je vhodný pro úplné začátečníky.</p>\r\n    </div>\r\n</div>\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-6\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Pro</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">1 až 2 účastníky</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-thumbs-up text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Věk</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">od 6 do 15 let</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-hand-holding-heart text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Cena</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">1 den / 1 os. / 3000 Kč</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-user-clock text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Délka kurzu</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">1 až 3 dny</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-calendar-days text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kdy</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">především o víkendech</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-map-location-dot text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kde</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">Celá ČR</p>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container px-4 mb-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-lg-2\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-sm-5 shadow-sm\">\r\n                    <div class=\"d-flex flex-column flex-sm-row align-items-start\">\r\n                        <div class=\"bg-white text-info rounded-4 d-flex align-items-center justify-content-center shadow-sm mb-4 mb-sm-0 me-sm-4 flex-shrink-0\" style=\"width: 70px; height: 70px;\">\r\n                            <i class=\"fa-solid fa-icons fs-2\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h4 class=\"fw-bold text-dark mb-3\">„Připravím akci na míru“</h4>\r\n                            <p class=\"lead mb-0\">Naplánuji výlet a zajistím veškerý servis. V ceně jsou zahrnuté všechny potřebné náklady: doprava, jídlo, profesionální průvodcovské služby, lodě, samozřejmostí je i bezpečnostní vybavení pro každého účastníka.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-sm-5 shadow-sm\">\r\n                    <div class=\"d-flex flex-column flex-sm-row align-items-start\">\r\n                        <div class=\"bg-white text-info rounded-4 d-flex align-items-center justify-content-center shadow-sm mb-4 mb-sm-0 me-sm-4 flex-shrink-0\" style=\"width: 70px; height: 70px;\">\r\n                            <i class=\"fa-solid fa-hand-sparkles fs-2\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h4 class=\"fw-bold text-dark mb-3\">Dobrodružství na dosah ruky</h4>\r\n                            <p class=\"lead mb-0\">I když se to nezdá, nemusíme za vodáckým dobrodružstvím cestovat stovky kilometrů, řeky kousek od Brna nabízí spoustu pěkných a vodácky zajímavých úseků. Nafukovací kánoe Pálava jsou určeny pro 2 osoby, a však může vést i dalšího malého námořníka uprostřed lodě.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-4 bg-white mb-5\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-sm-2 row-cols-md-3\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/voda1.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/voda2.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/voda3.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>', 1, '2025-04-03 17:47:43', '2026-06-12 20:57:25'),
(16, 'Lukostřelecké kurzy', 'lukostrelecke-kurzy', '<section><div class=\"px-4 py-1 my-5 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">STŘÍLÍME PŘEDEVŠÍM PRO RADOST</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Trénujeme soustředění, budujeme zodpovědnost, netrénujeme profesionální střelbu, jde nám o dobrou partu a poznání.</p>\r\n</div>\r\n</div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-6\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kurz</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">pro 1 až 4 účastníky</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-thumbs-up text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Věk</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">od 8 do 15 let</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-hand-holding-heart text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Cena</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">1 lekce / až 4 os. / 800 Kč</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-user-clock text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Délka lekce</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">2 hodiny</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-calendar-days text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kdy</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">pouze v létě dle domluvy</p>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-white rounded-4 p-3 shadow-sm text-center\">\r\n                    <i class=\"fa-solid fa-map-location-dot text-info fs-1 mb-3 mt-2 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-1 fs-6\">Kde</h5>\r\n                    <p class=\"fw-light small text-muted mb-0\">Základna Svobodům - Jindřichovice pod Smrkem 213</p>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<section class=\"py-5 bg-white\" id=\"featured-3\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-sm-2 row-cols-md-3\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk1.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk2.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk3.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 250px;\">\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container px-4 mb-5\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-lg-2\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-sm-5 shadow-sm\">\r\n                    <div class=\"d-flex flex-column flex-sm-row align-items-start\">\r\n                        <div class=\"bg-white text-info rounded-4 d-flex align-items-center justify-content-center shadow-sm mb-4 mb-sm-0 me-sm-4 flex-shrink-0\" style=\"width: 70px; height: 70px;\">\r\n                            <i class=\"fa-solid fa-bow-arrow fs-2\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h4 class=\"fw-bold text-dark mb-3\">Pravidelné i jednorázové kurzy</h4>\r\n                            <p class=\"text-muted mb-0\">Lekce je vhodná pro úplné začátečníky, kteří si chtějí lukostřelbu vyzkoušet nebo v krátkém čase naučit se základy přežití a sebeobrany.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col\">\r\n                <div class=\"card h-100 border-0 bg-light rounded-4 p-4 p-sm-5 shadow-sm\">\r\n                    <div class=\"d-flex flex-column flex-sm-row align-items-start\">\r\n                        <div class=\"bg-white text-info rounded-4 d-flex align-items-center justify-content-center shadow-sm mb-4 mb-sm-0 me-sm-4 flex-shrink-0\" style=\"width: 70px; height: 70px;\">\r\n                            <i class=\"fa-solid fa-handshake fs-2\"></i>\r\n                        </div>\r\n                        <div>\r\n                            <h4 class=\"fw-bold text-dark mb-3\">Lektor zajistí vhodné místo i vybavení</h4>\r\n                            <p class=\"text-muted mb-0\">V ceně lekce je zahrnuto, zapůjčení veškerého potřebného vybavení pro začátečníky, a také lektor který se bude věnovat začínajícímu střelci.</p>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-4 row-cols-1 row-cols-sm-2 row-cols-lg-2\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk5.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 300px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk6.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 300px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk8.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 300px;\">\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"overflow-hidden rounded-4 shadow-sm h-100 border border-secondary border-opacity-10\">\r\n                    <img src=\"/img/luk9.jpg\" alt=\"image_kid\" class=\"img-fluid w-100 h-100\" style=\"object-fit: cover; min-height: 300px;\">\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>', 1, '2025-04-03 17:51:41', '2026-06-12 20:49:34');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(17, 'Ceník', 'cenik', '[hlavicka typ=\"hero_banner\" title=\"Příroda je nejlepší učebna\" text=\"\" img=\"/img/slidelod.jpg\" overlay=\"0.3\"]\r\n\r\n\r\n<section class=\"py-5 bg-white\" id=\"cenik-detail\">\r\n    <div class=\"container py-4\">\r\n        \r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 600px;\">\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Připravím akci na míru</h2>\r\n            <p class=\"text-muted lead\">Kvalitně strávený volný čas se vyplatí Vám i dětem.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 bg-white p-4 p-xl-5 rounded-4 text-center shadow-sm d-flex flex-column border-bottom-0 border-start-0 border-end-0\" style=\"border-top: 4px solid #0284c7 !important;\">\r\n                    \r\n                    <div class=\"rounded-circle d-flex align-items-center justify-content-center mx-auto mb-4 shadow-sm flex-shrink-0\" style=\"width: 80px; height: 80px; background-color: #e0f2fe; color: #0284c7;\">\r\n                        <i class=\"fa-solid fa-person-hiking fs-2\"></i>\r\n                    </div>\r\n                    \r\n                    <h4 class=\"fw-bold text-dark mb-3\">Jednodenní výpravy</h4>\r\n                    <p class=\"text-muted mb-0 lh-base\">Při jednodenním výletě se svačinou z domova většinou utratíme <b>400 až 1000 Kč</b> za dopravu a nejrůznější vstupné, v ceně jsou i profesionální průvodcovské služby.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 bg-white p-4 p-xl-5 rounded-4 text-center shadow-sm d-flex flex-column border-bottom-0 border-start-0 border-end-0\" style=\"border-top: 4px solid #059669 !important;\">\r\n                    \r\n                    <div class=\"rounded-circle d-flex align-items-center justify-content-center mx-auto mb-4 shadow-sm flex-shrink-0\" style=\"width: 80px; height: 80px; background-color: #d1fae5; color: #059669;\">\r\n                        <i class=\"fa-solid fa-campground fs-2\"></i>\r\n                    </div>\r\n                    \r\n                    <h4 class=\"fw-bold text-dark mb-3\">Vícedenní expedice</h4>\r\n                    <p class=\"text-muted mb-0 lh-base\">Když jedeme na vícedenní výlet, jedna noc nás přijde na <b>500 Kč</b>, v ceně jsou zahrnuté náklady za dopravu, ubytování, jídlo, i profesionální průvodcovské služby.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 bg-white p-4 p-xl-5 rounded-4 text-center shadow-sm d-flex flex-column border-bottom-0 border-start-0 border-end-0\" style=\"border-top: 4px solid #7c3aed !important;\">\r\n                    \r\n                    <div class=\"rounded-circle d-flex align-items-center justify-content-center mx-auto mb-4 shadow-sm flex-shrink-0\" style=\"width: 80px; height: 80px; background-color: #ede9fe; color: #7c3aed;\">\r\n                        <i class=\"fa-solid fa-toolbox fs-2\"></i>\r\n                    </div>\r\n                    \r\n                    <h4 class=\"fw-bold text-dark mb-3\">Kroužky a dovednosti</h4>\r\n                    <p class=\"text-muted mb-0 lh-base\">Během roku se scházíme jednou týdně venku ale i v pronajatých klubovnách. Účastníci mají v ceně i profesionálního lektora, notebook, klubovnu. Ceny se pohybují kolem <b>400 - 1000 Kč</b> za měsíc.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n    \r\n    \r\n    \r\n    \r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<section class=\"py-5 bg-light border-top\" id=\"aktivity\">\r\n<div class=\"container py-3\">\r\n<div class=\"text-center mb-5 mx-auto\" style=\"max-width: 750px;\">\r\n<div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\"><hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">Orientační ceny<hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\"></div>\r\n<h2 class=\"display-5 fw-bold text-dark mb-3\">Kolik stojí naše dobrodružství</h2>\r\n<p class=\"lead text-muted mb-4\">Bez vaší finanční podpory nemůžeme dělat to, co děláme; shledáváte-li naši činnost smysluplnou, budu rád, když naši práci oceníte.</p>\r\n</div>\r\n    \r\n     <div class=\"row g-4\">\r\n    <div class=\"col-lg-4\">\r\n        <div class=\"activity-card h-100 p-0 overflow-hidden d-flex flex-column\" style=\"--theme-color: #0284c7;\">\r\n            <div class=\"bg-white p-4 border-bottom\">\r\n                <i class=\"fa-solid fa-compass activity-icon mb-3\" style=\"color: #0284c7;\"></i>\r\n                <h4 class=\"fw-bold fs-5 mb-1\">Průvodcovské služby</h4>\r\n                <p class=\"text-muted small mb-0\">Pro jednotlivce i skupiny</p>\r\n            </div>\r\n            <div class=\"p-4 flex-grow-1\">\r\n                <ul class=\"list-unstyled mb-0\">\r\n                    <li class=\"d-flex justify-content-between align-items-center mb-3\"><span class=\"text-muted fw-medium small\">1 hodina / 1 os.</span> <strong class=\"text-dark\">250 Kč</strong></li>\r\n                    <li class=\"d-flex justify-content-between align-items-center mb-4\"><span class=\"text-muted fw-medium small\">Celý den / 1 os.</span> <strong class=\"text-dark\">1 500 Kč</strong></li>\r\n                </ul>\r\n                <h6 class=\"fw-bold text-dark mb-3 border-top pt-4\">Zážitková víkendovka</h6>\r\n                <ul class=\"list-unstyled mb-0\">\r\n                    <li class=\"d-flex justify-content-between align-items-center mb-2\"><span class=\"text-muted small\">1 os. / den</span> <strong class=\"text-dark\">1 000 Kč</strong></li>\r\n                    <li>\r\n                        <div class=\"a