INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(19, 'Tools', 'tools', 'c1\r\n<section class=\"overflow-hidden\">\r\n	<div class=\"container\">\r\n\r\n\r\n		<div\r\n			class=\"row g-4\">\r\n			<!-- Feature content START -->\r\n			<div\r\n				class=\"col-lg-6 mb-sm-6 mb-lg-0\">\r\n				<!-- Title -->\r\n				<h2 class=\"mb-4\">\r\n					<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content1\" data-id=\"104\">Vytvořte moderní e-shop</span>\r\n				</h2>\r\n				<p class=\"mb-0\">\r\n					<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content2\" data-id=\"104\">Redakční systém obsahuje veškeré funkce pro správu e-shopu.</span>\r\n				</p>\r\n\r\n				<hr class=\"my-4 my-sm-5\">\r\n				<!-- Divider -->\r\n\r\n				<!-- Features item -->\r\n					<div class=\"row g-4 mb-4 mb-sm-5\"> <div\r\n						class=\"col-sm-6\">\r\n						<!-- Items -->\r\n						<div\r\n							class=\"d-flex mb-4 mb-sm-5\">\r\n							<!-- Icon -->\r\n							<div class=\"icon-md flex-shrink-0 text-primary bg-primary bg-opacity-10 rounded-circle\">\r\n								<i class=\"bi bi-truck-flatbed fa-xl\"></i>\r\n							</div>\r\n							<!-- Content -->\r\n							<div class=\"ms-3\">\r\n								<h6 class=\"mb-0 mb-sm-2\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content3\" data-id=\"104\">Odesílání zboží</span>\r\n								</h6>\r\n								<p class=\"mb-0\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content4\" data-id=\"104\">Možnost napojení na dopravní společnosti jako je Zásilkovna.</span>\r\n								</p>\r\n							</div>\r\n						</div>\r\n\r\n						<!-- Items -->\r\n						<div\r\n							class=\"d-flex\">\r\n							<!-- Icon -->\r\n							<div class=\"icon-md flex-shrink-0 text-primary bg-primary bg-opacity-10 rounded-circle\">\r\n								<i class=\"bi bi-boxes fa-xl\"></i>\r\n							</div>\r\n							<!-- Content -->\r\n							<div class=\"ms-3\">\r\n								<h6 class=\"mb-0 mb-sm-2\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content5\" data-id=\"104\">Propojení s bankou</span>\r\n								</h6>\r\n								<p class=\"mb-0\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content6\" data-id=\"104\">Automatické párování všech plateb s objednávkami.</span>\r\n								</p>\r\n							</div>\r\n						</div>\r\n					</div>\r\n\r\n					<div\r\n						class=\"col-sm-6\">\r\n						<!-- Items -->\r\n						<div\r\n							class=\"d-flex mb-4 mb-sm-5\">\r\n							<!-- Icon -->\r\n							<div class=\"icon-md flex-shrink-0 text-primary bg-primary bg-opacity-10 rounded-circle\">\r\n								<i class=\"bi bi-people fa-xl\"></i>\r\n							</div>\r\n							<!-- Content -->\r\n							<div class=\"ms-3\">\r\n								<h6 class=\"mb-0 mb-sm-2\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content7\" data-id=\"104\">Platební brána</span>\r\n								</h6>\r\n								<p class=\"mb-0\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content8\" data-id=\"104\">Zákazníci mohou platit kartou, převodem, i Bitcoinem.</span>\r\n								</p>\r\n							</div>\r\n						</div>\r\n\r\n						<!-- Items -->\r\n						<div\r\n							class=\"d-flex\">\r\n							<!-- Icon -->\r\n							<div class=\"icon-md flex-shrink-0 text-primary bg-primary bg-opacity-10 rounded-circle\">\r\n								<i class=\"bi bi-shield-check fa-xl\"></i>\r\n							</div>\r\n							<!-- Content -->\r\n							<div class=\"ms-3\">\r\n								<h6 class=\"mb-0 mb-sm-2\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" data-language=\"cs\" data-column=\"content9\" data-id=\"104\">Vedení učetnictví</span>\r\n								</h6>\r\n								<p class=\"mb-0\">\r\n									<span contenteditable=\"false\" class=\"editable-element\" 