INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(20, 'Test', 'test', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní školka pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2025-04-15 03:57:55', '2026-06-11 10:43:43'),
(21, 'KidHub', 'kidhub', '<div class=\"container py-5\">\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold text-black\">KidHub – prostor pro růst a nápady</h1>\r\n<div class=\"col-lg-8 mx-auto\"><!-- Lehce přeformulovaný text -->\r\n<p class=\"lead mb-4\">Každý příspěvek posouvá náš projekt k vytvoření platformy sebeřízeného vzdělávání a inovací.</p>\r\n</div>\r\n</div>\r\n<!-- Projekt box s carouselem vlevo a textem vpravo -->\r\n<div class=\"row g-5 align-items-center mt-0\">\r\n<div class=\"col-md-6\"><!-- Carousel: slide show místo statického obrázku -->\r\n<div id=\"carouselExampleIndicators\" class=\"carousel slide\" data-bs-ride=\"carousel\">\r\n<ol class=\"carousel-indicators\">\r\n<li data-bs-target=\"#carouselExampleIndicators\" data-bs-slide-to=\"0\" class=\"active\"></li>\r\n<li data-bs-target=\"#carouselExampleIndicators\" data-bs-slide-to=\"1\"></li>\r\n<li data-bs-target=\"#carouselExampleIndicators\" data-bs-slide-to=\"2\"></li>\r\n</ol>\r\n<div class=\"carousel-inner\">\r\n<div class=\"carousel-item active\"><img src=\"/img/uploads/24/b2.jpg\" class=\"d-block w-100 rounded shadow-sm\" alt=\"Slide 1\"></div>\r\n<div class=\"carousel-item\"><img src=\"/img/uploads/24/b3.jpg\" class=\"d-block w-100 rounded shadow-sm\" alt=\"Slide 2\"></div>\r\n<div class=\"carousel-item\"><img src=\"/img/uploads/24/b4.jpg\" class=\"d-block w-100 rounded shadow-sm\" alt=\"Slide 3\"></div>\r\n</div>\r\n<a class=\"carousel-control-prev\" href=\"#carouselExampleIndicators\" role=\"button\" data-bs-slide=\"prev\"> <span class=\"carousel-control-prev-icon\" aria-hidden=\"true\"></span> </a> <a class=\"carousel-control-next\" href=\"#carouselExampleIndicators\" role=\"button\" data-bs-slide=\"next\"> <span class=\"carousel-control-next-icon\" aria-hidden=\"true\"></span> </a></div>\r\n<div class=\"mt-5\">\r\n<div class=\"bg-light rounded p-4 shadow-sm\">\r\n<h4 class=\"text-primary\">Váš příspěvek má smysl</h4>\r\n<p>Každá vaše investice pomáhá umožnit dětem účastnit se kurzů a výletů, objevovat svět, učit se nové dovednosti. Každá investice posouvá náš projekt k vytvoření inovativní platformy pro sebeřízené vzdělávání, která nabízí příležitost a svobodu pro budoucí generace.</p>\r\n<p>Každý příspěvek pomáhá vytvořit prostředí plné radosti, respektu a svobody.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\"col-md-6\">\r\n<h3 class=\"text-black mb-3\">Investujte do vzdělání dětí</h3>\r\n<p class=\"mb-4\">Některé děti by se rády účastnily našich výletů a kurzů, jejichž rodiče si to nemohou dovolit. Vaše podpora pokryje náklady na zkušeného lektora, který se dětem bude naplno věnovat a vytvoří pro ně respektující a inspirující prostředí.</p>\r\n<!-- Upravený titulek s důrazem na investici -->\r\n<h3 class=\"text-black mb-3\">Malí tvůrci ale velké nápady</h3>\r\n<p class=\"mb-4\">Zde můžete snadno financovat inovativní projekt, Vaše investice otevírá dětem cestu k prostředí, který staví na principech sebeřízeného vzdělávání, svobodě, respekt a osobní růst.</p>\r\n<!-- Progress bar -->\r\n<div class=\"progress mb-3\" role=\"progressbar\" aria-valuenow=\"45\" aria-valuemin=\"0\" aria-valuemax=\"100\">\r\n<div class=\"progress-bar progress-bar-striped bg-warning\" style=\"width: 45%;\"></div>\r\n</div>\r\n<p class=\"text-muted small\">Vybráno 4 500 Kč z 20 000 Kč</p>\r\n<!-- Box kolem počtu hodin -->\r\n<div class=\"border border-primary rounded p-2 mb-3 d-inline-block\"><strong>200 hodin</strong></div>\r\n<p class=\"text-muted small\">Vaše investice přináší zážitky, buduje vztahy a podporuje prostředí svobody, kde se učí nejen znalosti, ale i hodnoty samostatnosti.</p>\r\n<!-- Upravené tlačítko s výzvou k investici --> <a href=\"#\" class=\"btn btn-primary\"> <i class=\"fad fa-donate me-2\"></i>Přispět – investujte ihned </a>\r\n<p>Každá částka je krokem kupředu.</p>\r\n<!-- Další informace --></div>\r\n</div>\r\n</div>\r\n<p>{{-- Nápady na další formulace, které lze použít v rámci projektu: 1. \"Investujte do budoucnosti – každý příspěvek rozvíjí platformu sebeřízeného vzdělávání a přináší inovativní prostředí, kde se rodí nové příležitosti.\" 2. \"Vaše investice je klíčovým prvkem projektu, který staví na hodnotách sebeřízení, respektu a svobody. Kupujete produkt, který rozvíjí potenciál budoucnosti.\" 3. \"Podpořte projekt a investujte do platformy, kde se mládež učí nejen akademické dovednosti, ale i životní zkušenosti a hodnoty samostatnosti.\" 4. \"Přispějte a staňte se součástí inovativního projektu, který mění způsob vzdělávání – investujete do budoucnosti plné příležitostí.\" --}}</p>\r\n<div class=\"container py-5\">\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold text-black\">Pomozte dětem k vzdělání a zážitkům</h1>\r\n<div class=\"col-lg-8 mx-auto\">\r\n<p class=\"lead mb-4\">Každý příspěvek pomáhá umožnit dětem účastnit se kurzů a výletů, objevovat svět, učit se nové dovednosti.</p>\r\n</div>\r\n</div>\r\n. <!-- Projekt box s obrázkem vlevo a textem vpravo -->\r\n<div class=\"row g-5 align-items-center mt-0\">\r\n<div class=\"col-md-6\"><img src=\"/img/uploads/24/b2.jpg\" class=\"img-fluid rounded shadow-sm\" alt=\"Děti na výletě\"></div>\r\n<div class=\"col-md-6\">\r\n<h3 class=\"text-black mb-3\">Pomáháte vytvořit svět, kde žádné dítě nemusí zůstat doma</h3>\r\n<p class=\"mb-4\">Některé děti by se rády účastnily našich výletů a kurzů, jejichž rodiče si to nemohou dovolit. Vaše podpora pokryje náklady na zkušeného lektora, který se dětem bude naplno věnovat a vytvoří pro ně respektující a inspirující prostředí.</p>\r\n<!-- Progress bar -->\r\n<div class=\"progress mb-3\" role=\"progressbar\" aria-valuenow=\"45\" aria-valuemin=\"0\" aria-valuemax=\"100\">\r\n<div class=\"progress-bar progress-bar-striped bg-warning\" style=\"width: 45%;\"></div>\r\n</div>\r\n<p class=\"text-muted small\">Vybráno 4 500 Kč z 20 000 Kč</p>\r\n<p>200 hodin</p>\r\n<p class=\"text-muted small\">Vaše pomoc přináší zážitky, buduje vztahy, vytváří nezapomenutelné momenty a podporuje</p>\r\n<a href=\"#\" class=\"btn btn-primary\"><i class=\"fad fa-donate me-2\"></i>Přispět můžete ihned vložením bankovek</a>\r\n<p>Každá částka pomáhá.</p>\r\n<!-- Další informace -->\r\n<div class=\"mt-5\">\r\n<div class=\"bg-light rounded p-4 shadow-sm\">\r\n<h4 class=\"text-primary\">Vaše pomoc má smysl</h4>\r\n<p>Každý příspěvek pomáhá vytvořit prostředí plné radosti, respektu a svobody.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p>Různé formulace textů: Mnoho dětí touží objevovat svět, učit se nové dovednosti a být součástí něčeho většího. Díky vašemu příspěvku to bude možné i pro ty, jejichž rodiče si to nemohou dovolit. Věříme v respektující přístup, podporu svobody a rozvoj každého dítěte. Pomáháte vytvořit svět, kde žádné dítě není pozadu jen kvůli penězům. které by si jinak nemohly dovolit. Podpořte dobrodružné projekty pro děti Váš příspěvek zafinancuje zkušeného lektora, pomůcky a dopravu tak, aby žádné dítě nemuselo zůstat doma. Tento projekt jim dává šanci. Váš příspěvek zafinancuje zkušeného lektora, pomůcky a dopravu tak, aby žádné dítě nemuselo zůstat doma. Díky vašemu příspěvku to bude možné i pro ty, jejichž rodiče si to nemohou dovolit. Díky vašemu příspěvku mohou i tyto děti zažít dobrodružství, vzdělávat se v respektujícím prostředí. Vaše podpora pokryje náklady na zkušeného lektora, který se dětem bude naplno věnovat a vytvoří pro ně bezpečné a inspirativní prostředí. Váš příspěvek zafinancuje zkušeného lektora, pomůcky a dopravu tak, aby žádné dítě nemuselo zůstat doma. Bohužel, ne všechny rodiny si mohou dovolit zaplatit dětem tyto aktivity. Mnoho dětí touží objevovat svět, učit se nové dovednosti a účastnit se našich kurzů a výprav. Bohužel, ne všechny rodiny si mohou dovolit zaplatit dětem tyto aktivity. Vaše pomoc přináší zážitky, buduje vztahy, vytváří nezapomenutelné momenty a podporuje</p>\r\n<!-- Kontakt nebo výzva -->\r\n<div class=\"text-center mt-5\">\r\n<h5 class=\"text-primary mb-3\">Chcete se zapojit i jinak?</h5>\r\n<p>Ozvěte se nám, pokud byste chtěli přispět jako lektor, dobrovolník nebo pomoci s organizací.</p>\r\n<a href=\"/kontakt\" class=\"btn btn-outline-primary\">Kontaktujte nás</a></div>\r\n<div class=\"container py-5\">\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold text-black\">Podpořte dobrodružné projekty pro děti</h1>\r\n<div class=\"col-lg-8 mx-auto\">\r\n<p class=\"lead mb-4\">Každý příspěvek pomáhá vytvořit prostředí plné radosti, respektu a svobody. Vyberte si projekt, který vám dává smysl.</p>\r\n</div>\r\n</div>\r\n<!-- Karty s projekty -->\r\n<div class=\"row row-cols-1 row-cols-md-3 g-4 mt-5\">@foreach (range(1,3) as $i)\r\n<div class=\"col\">\r\n<div class=\"card h-100 shadow-sm border-light\"><img src=\"/img/uploads/24/b2.jpg\" class=\"card-img-top\" alt=\"Projekt {{ $i }}\">\r\n<div class=\"card-body\">\r\n<h5 class=\"card-title text-primary\">Projekt č.{{ $i }}</h5>\r\n<p class=\"card-text\">Pomozte nám uskutečnit tento výjimečný projekt zaměřený na rozvoj dětí a pobyt v přírodě.</p>\r\n<!-- Progress bar -->\r\n<div class=\"progress mb-2\" role=\"progressbar\" aria-valuenow=\"30\" aria-valuemin=\"0\" aria-valuemax=\"100\">\r\n<div class=\"progress-bar progress-bar-striped bg-warning\" style=\"width: 30%;\"></div>\r\n</div>\r\n<p class=\"text-muted small\">Vybráno 3 000 Kč z 10 000 Kč</p>\r\n<a href=\"#\" class=\"btn btn-primary w-100\">Přispět <i class=\"fad fa-donate ms-2\"></i></a></div>\r\n</div>\r\n</div>\r\n@endforeach</div>\r\n<!-- Info sekce -->\r\n<div class=\"mt-5\">\r\n<div class=\"bg-light rounded p-4\">\r\n<h4>Proč přispět?</h4>\r\n<p>Mnoho dětí touží objevovat svět, učit se nové dovednosti a účastnit se našich kurzů a výprav. Bohužel, ne všechny rodiny si mohou dovolit zaplatit dětem tyto aktivity. Díky vašemu příspěvku mohou i tyto děti zažít dobrodružství, vzdělávat se v respektujícím prostředí a růst v komunitě. Vaše podpora pokryje náklady na zkušeného lektora, který se dětem bude naplno věnovat a vytvoří pro ně bezpečné a inspirativní prostředí. Vaše pomoc přináší zážitky, buduje vztahy, vytváří nezapomenutelné momenty a podporuje svobodnou výchovu dětí.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<!-- Pruh s ikonami -->\r\n<div class=\"bg-light rounded mt-5 shadow-sm\">\r\n<div class=\"container px-4 py-4\">\r\n<div class=\"row row-cols-1 row-cols-lg-5 g-4 text-center\">\r\n<div class=\"feature col text-center\">\r\n<h3></h3>\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Kamarádi</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-campground text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Dobrodružství</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-tree text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Pobyt v přírodě</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-compass text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Dovednosti</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Respekt</h5>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<div class=\" bg-light\">\r\n<div class=\"container px-4 mt-4 mt-5 my-4 py-0\">\r\n<div class=\" row g-4 py-5 row-cols-1 row-cols-lg-5\">\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Kamarádi</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-campground text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Dobrodružství</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-tree text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Pobyt v přírodě</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-compass text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Dovednosti</h5>\r\n</div>\r\n<div class=\"feature col text-center\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h5>Respekt</h5>\r\n</div>\r\n</div>\r\n</div>\r\n</div>', 1, '2025-04-15 07:11:20', '2026-06-11 14:30:28'),
(22, 'Sebeřízené vzdělávání', 'home', '[hlavicka typ=\"hero_default\" title1=\"Putujeme přírodou a učíme se novým dovednostem\" text1=\"Provázím mladé dobrodruhy na cestách za poznáním\" img1=\"/img/slideohen.jpg\" title2=\"Nabízím zážitky na celý život\" text2=\"výlety I expedice I vzdělávací kurzy\" img2=\"/img/slidelod.jpg\" title3=\"Vytvářím pro děti příležitosti k seberozvoji\" text3=\"A trávíme čas ve zdravém prostředí\" img3=\"/img/slidealex.jpg\"]\r\n\r\n[blok typ=\"blok_nadpis1\" podnadpis=\"Dobrodruzi.cz\" nadpis=\"Sebeřízené vzdělávání\" text=\"Vytvářím pro děti z Jindřichovic pod Smrkem <strong>příležitosti</strong> k všestrannému rozvoji, pořádám výlety, expedice, kurzy, kroužky, věnujeme se vzdělávání, praktickým dovednostem, a dalším volnočasovým aktivitám a hrám.\"]\r\n\r\n[blok typ=\"blok_uvod\" nadpis=\"Putujeme přírodou a učíme se novým dovednostem\" text1=\"S dětmi zkoumám svět, bádáme, učíme se a hrajeme si, se staršími dobrodruhy společně plánujeme a uskutečňujeme velká dobrodružství.\" text2=\"Na cestách najdou vaše děti nové přátele a zažijí spoustu zábavy a dobrodružství.\" odkaz_url=\"https://dobrodruzi.cz/cs/stranka/vylety\" odkaz_ikona=\"fa-solid fa-person-hiking\" odkaz_text=\"Výlety do přírody\" obrazek_src=\"/img/obr5.jpg\" obrazek_alt=\"Děti putující přírodou\"]\r\n\r\n\r\n[blok typ=\"blok_nadpis2\" nadpis=\"Víc než jen zábava\" text=\"Na výletech a kurzech děti rozvíjejí sebedůvěru, samostatnost, férovost, spolupráci. Učí se žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.\"]\r\n\r\n\r\n[blok typ=\"blok_karty3\" ikona1=\"fa-solid fa-person-hiking\" nadpis1=\"Výlety\" text1=\"Cestovatelské a tábornické znalosti, dovednosti přežití. Zkušený průvodce, respektující přístup a spousta zábavy.\" ikona2=\"fa-solid fa-users\" nadpis2=\"Kroužky\" text2=\"Většinu času trávíme v pohybu, v přírodě, za každého počasí. Věnujeme se, pohybovým hrám a vzdělávacím činnostem.\" ikona3=\"fa-solid fa-campground\" nadpis3=\"Kurzy\" text3=\"Nabízím vzdělávací činnosti, výuku programování, sjíždění řek na nafukovacích kánojích, cestovatelské dovednosti a znalosti.\"]\r\n\r\n[blok typ=\"blok_knihy\" obrazek_src=\"/img/knihy.png\" obrazek_alt=\"Respektující literatura\" podnadpis=\"Knihy, ze kterých vycházím\" nadpis=\"Respekt, svoboda, zodpovědnost​\" text=\"Klíčem ke spokojenému životu jsou dobré mezilidské vztahy, ty představují zdroj většiny radostí i bolestí v lidském životě. Mladí dobrodruzi pěstují vztahy založené na vzájemném respektu a úctě.​\" tlacitko1_url=\"https://www.peoplecomm.cz/respektovat-a-byt-respektovan\" tlacitko1_text=\"Respektovat a být res.\" tlacitko2_url=\"https://www.peoplecomm.cz/kniha-summerhill\" tlacitko2_text=\"Demokratická škola\" tlacitko3_url=\"https://www.peoplecomm.cz/svoboda-uceni\" tlacitko3_text=\"​​Svoboda učení\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_nadpis3\" nadpis=\"Dávám možnost říct <span class=\'text-info\'>„ne“</span>\" text=\"Ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a potřeb, následně společně tvoříme přijatelná řešení. Akceptuji volbu a přirozené následky.\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_karty2\" ikona1=\"fa-solid fa-arrows-alt\" nadpis1=\"Připravuji řízený program formou nabídky\" text1=\"Využívám <strong>vnitřní motivace</strong> dětí, aby se mohly věnovat věcem proto, že v nich vidí <strong>smysl</strong>, že je baví a že samy chtějí.\" ikona2=\"fa-solid fa-handshake-angle\" nadpis2=\"„Jsem pro děti parťák, nikoli diktátor“\" text2=\"Děti vedu k samostatnosti, přistupuji k nim individuálně a s <strong>respektem</strong>. Zajišťuji bezpečné a motivující prostředí, ve kterém se mohou všestranně rozvíjet. Dávám jim prostor pro volnou hru a svobodné učení.\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_obrazky_texty\" podnadpis=\"Bezpečný rozvoj\" nadpis=\"Učíme se prostřednictvím přírody\" text_uvod=\"Volnočasové aktivity organizuji převážně v přírodě, protože pobyt venku a pohyb na čerstvém vzduchu podporuje zdraví a odolnost dětí. Děti poznávají okolí místa, kde žijí, osvojují si praktické cestovatelské dovednosti a učí se rozpoznat přirozená nebezpečí.\" obr1_src=\"/img/sm-b1.jpg\" obr1_alt=\"Děti v kolektivu\" text1=\"Děti se učí žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.\" obr2_src=\"/img/sm-b4.jpg\" obr2_alt=\"Kreativita dětí\" text2=\"Vytvářejí si pozitivní vztah sami k sobě, a neustále na sobě pracují. Podporujeme jejich kreativitu a zručnost.\" obr3_src=\"/img/sm-b2.jpg\" obr3_alt=\"Rituály a přátelství\" text3=\"Poznávají hodnotu přátelství a sdílení, prožívají společně rituály. Osvojují si správné řešení konfliktů a efektivní komunikaci.\"]\r\n\r\n\r\n\r\n\r\n[blok typ=\"blok_info_karty\" ikona1=\"fa-solid fa-map-location-dot\" nadpis1=\"Místa konání\" text1=\"Scházíme se v Jindřichovicích pod Smrkem, nejlepší učebna je sama příroda, v létě i v zimě využíváme zázemí <a href=\'https://goo.gl/maps/itTNU4573LkMN6Jj7\' target=\'_blank\' class=\'text-info fw-semibold text-decoration-none\'>základny</a> Svobodům.\" odkaz1_url=\"https://goo.gl/maps/itTNU4573LkMN6Jj7\" odkaz1_text=\"Zobrazit mapu\" ikona2=\"fa-solid fa-calendar-days\" nadpis2=\"Termíny akcí\" text2=\"Na výlety vyrážíme o víkendech, kurzy a kroužky se konají ve všední dny.\" odkaz2_url=\"https://dobrodruzi.cz/rezervace/\" odkaz2_text=\"Zobrazit kalendář\" ikona3=\"fa-solid fa-hand-holding-heart\" nadpis3=\"Ceny\" text3=\"Dopravu, jídlo a ubytování na výletech si hradí děti sami (výdaje v řádu stokorun). Více informací najdete na stránce cen.\" odkaz3_url=\"https://dobrodruzi.cz/cs/stranka/cenik\" odkaz3_text=\"Přejít na Ceny\"]\r\n\r\n\r\n\r\n\r\n[blok typ=\"blok_kurzy_prog\" ikona=\"fa-solid fa-laptop-code\" nadpis=\"Nyní jsou nejžádanější kurzy programování\" text=\"Děti učím programovat, vytváříme počítačové hry, a trávíme čas ve zdravém prostředí.\" odkaz1_url=\"https://dobrodruzi.cz/cs/stranka/kurzy-programovani\" odkaz1_text=\"Více o kurzech »\" odkaz2_url=\"https://dobrodruzi.cz/rezervace/\" odkaz2_text=\"Volné termíny »\"]\r\n\r\n\r\n [blok typ=\"blok_kurzy_prog_detail\" badge=\"Technika venku\" title=\"Píšeme programátorský kód přímo v přírodě\" text=\"Kdo říká, že technologie patří jen do tmavých pokojů? Naše expedice kombinují pobyt na čerstvém vzduchu s rozvojem logického myšlení.\" img=\"/img/uploads/41/b20.jpg\" list1=\"Respektující přístup a práce vlastním tempem\" list2=\"Spojení moderních technologií a pobytu venku\" list3=\"Řešení reálných technických problémů\" btn_text=\"Prohlédnout aktivity\" btn_link=\"cs/stranka/kurzy-programovani\"]', 1, '2025-09-05 15:16:24', '2026-06-14 06:43:35');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(23, 'záloha úvod', 'zaloha-uvod', '<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Sebeřízené vzdělávání</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Vytvářím pro děti z Jindřichovic pod Smrkem <strong>příležitosti</strong> k všestrannému rozvoji, pořádám výlety, expedice, kurzy, kroužky, věnujeme se vzdělávání, praktickým dovednostem, a dalším volnočasovým aktivitám a hrám.</p>\r\n</div>\r\n</div>\r\n<div class=\"pink-100\">\r\n<div class=\"container col-xxl-8 px-4 py-1\">\r\n<div class=\"row align-items-center g-5 py-5\"><!-- Levý sloupec: Text -->\r\n<div class=\"col-12 col-lg-6\">\r\n<h2 class=\"fw-bold lh-sm mb-3\">\r\n    Putujeme přírodou a učíme se novým dovednostem\r\n</h2>\r\n<p class=\"lead lh-sm mb-4\">S dětmi zkoumám svět, bádáme, učíme se a hrajeme si, se staršími dobrodruhy společně plánujeme a uskutečňujeme velká dobrodružství.</p>\r\n<p class=\"lead mb-4\">Na cestách najdou vaše děti nové přátele a zažijí spoustu zábavy a dobrodružství.</p>\r\n<a class=\"btn btn-primary btn-lg px-4\" href=\"https://dobrodruzi.cz/cs/stranka/vylety\">Výlety do přírody »</a></div>\r\n<!-- Pravý sloupec: Obrázek -->\r\n<div class=\"col-12 col-lg-6\"><img class=\"d-block mx-lg-auto img-fluid\" style=\"border-radius: 2%;\" src=\"/img/obr5.jpg\" alt=\"popis\" width=\"600\" height=\"600\" loading=\"lazy\"></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Víc než jen zábava</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Na výletech a kurzech děti rozvíjejí sebedůvěru, samostatnost, férovost, spolupráci. Učí se žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.</p>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"bg-light  mb-5 mt-2\">\r\n<div class=\"container marketing col-xxl-8 px-4 py-5\"><!-- Three columns of text below the carousel -->\r\n<div class=\"row\">\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-hiking text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Výlety​</h3>\r\n<p class=\"fw-light\">Cestovatelské a tábornické znalosti, dovednosti přežití. Zkušený průvodce, respektující přístup a spousta zábavy.​</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"https://dobrodruzi.cz/cs/stranka/vylety\" role=\"button\">Více o výletech​ »</a></div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-users text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Kroužky​</h3>\r\n<p class=\"fw-light\">Většinu času trávíme v pohybu, v přírodě, za každého počasí. Věnujeme se, pohybovým hrám a vzdělávacím činnostem.​</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"https://dobrodruzi.cz/cs/stranka/lukostrelecke-kurzy\" role=\"button\" target=\"_blank\" rel=\"noopener\">Více i kroužcích​ »</a></div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-campground text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Kurzy​</h3>\r\n<p class=\" fw-light\">Nabízím vzdělávací činnosti, výuku programování, sjíždění řek na nafukovacích kánojích, cestovatelské dovednosti a znalosti. ​</p>\r\n<a class=\"btn btn-outline-secondary\" href=\"https://dobrodruzi.cz/cs/stranka/kurzy-programovani\" role=\"button\">Více o kurzech »</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"container col-xxl-8 px-4 py-1\">\r\n<div class=\"row flex-lg-row-reverse align-items-center g-5 py-5\">\r\n<div class=\"col-12 col-sm-12 col-lg-6\"><img src=\"/img/knihy.png\" class=\"d-block mx-lg-auto img-fluid\" alt=\"popis\" width=\"600\" height=\"600\" loading=\"lazy\"></div>\r\n<div class=\"col-lg-6\">\r\n<h3 class=\"display-7 fw-bold lh-sm mb-3\">Respekt, svoboda, zodpovědnost​</h3>\r\n<p class=\"lead\">Klíčem ke spokojenému životu jsou dobré mezilidské vztahy, ty představují zdroj většiny radostí i bolestí v lidském životě. Mladí dobrodruzi pěstují vztahy založené na vzájemném respektu a úctě.​</p>\r\n<div class=\"d-grid gap-2 d-md-flex justify-content-md-start\"><a href=\"https://www.peoplecomm.cz/respektovat-a-byt-respektovan\" type=\"button\" class=\"btn btn-outline-secondary\">Respektovat a být res. »</a> <a href=\"https://www.peoplecomm.cz/kniha-summerhill\" type=\"button\" class=\"btn btn-outline-secondary\">Demokratická škola »</a> <a href=\"https://www.peoplecomm.cz/svoboda-uceni\" type=\"button\" class=\"btn btn-outline-secondary\">​​Svoboda učení »</a></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"text-black px-4 pt-5 pb-5 mt-5 my-5 text-center bg-light\">\r\n<h1 class=\"display-6\">Dávám možnost říct<span class=\"text-primary\"> „ne“</span></h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a potřeb, následně společně tvoříme přijatelná řešení. Akceptuji volbu a přirozené následky.</p>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\" container px-4 py-5\" id=\"hanging-icons\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-2\">\r\n<div class=\"col d-flex align-items-start\">\r\n<div class=\"icon-square text-dark flex-shrink-0 me-3\"><i class=\"fas fas fa-arrows-alt text-primary rounded\" style=\"font-size: 45px; padding: 0px;\"> </i></div>\r\n<div>\r\n<h4 class=\"display-7\">Připravuji řízený program formou nabídky</h4>\r\n<p>Využívám <b>vnitřní motivace</b> dětí, aby se mohly věnovat věcem proto, že v nich vidí <b>smysl</b>, že je baví a že samy chtějí.</p>\r\n</div>\r\n</div>\r\n<div class=\"col d-flex align-items-start\">\r\n<div class=\"icon-square text-dark flex-shrink-0 me-3\"><i class=\"fas fas fa-handshake text-primary  rounded\" style=\"font-size: 45px; padding: 0px;\"> </i></div>\r\n<div>\r\n<h4 class=\"display-7\">„Jsem pro děti parťák, nikoli diktátor“</h4>\r\n<p>Děti vedu k samostatnosti, přistupuji k nim individuálně a s <b>respektem</b>. Zajišťuji bezpečné a motivující prostředí, ve kterém se mohou všestranně rozvíjet. Dávám jim prostor pro volnou hru a svobodné učení.</p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"px-4 py-1 my-0 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Učíme se prostřednictvím přírody</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Volnočasové aktivity organizuji převážně v přírodě, protože pobyt venku a pohyb na čerstvém vzduchu podporuje zdraví a odolnost dětí. Děti poznávají okolí místa, kde žijí, osvojují si praktické cestovatelské dovednosti a učí se rozpoznat přirozená nebezpečí.</p>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"container px-4 py-0\" id=\"featured-3\">\r\n<div class=\"row g-4 py-5 row-cols-1 row-cols-lg-3\">\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/sm-b1.jpg\" alt=\"\" class=\"img-fluid\"></p>\r\n<!--<h3 class=\"fs-5\"></h3>-->\r\n<p class=\"fw-light lh-base\">Děti se učí žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.</p>\r\n</div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/sm-b4.jpg\" alt=\"\" class=\"img-fluid\"></p>\r\n<!--<h3 class=\"fs-5\"></h3>-->\r\n<p class=\"fw-light lh-base\">Vytvářejí si pozitivní vztah sami k sobě, a neustále na sobě pracují. Podporujeme jejich kreativitu a zručnost.</p>\r\n</div>\r\n<div class=\"feature col\">\r\n<p><img src=\"/img/sm-b2.jpg\" alt=\"\" class=\"img-fluid\"></p>\r\n<!--<h3 class=\"fs-5\"></h3>-->\r\n<p class=\"fw-light lh-base\">Poznávají hodnotu přátelství a sdílení, prožívají společně rituály. Osvojují si správné řešení konfliktů a efektivní komunikaci.</p>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"bg-light  mb-5 mt-2\">\r\n<div class=\"container marketing col-xxl-8 px-4 py-5\"><!-- Three columns of text below the carousel -->\r\n<div class=\"row\">\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-map-marked-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Místa konání​</h3>\r\n<p class=\"fw-light\">Scházíme se v Brně a okolí, nejlepší učebna je sama příroda, v zimě hledáme úkryt v různých ​ <a href=\"https://goo.gl/maps/itTNU4573LkMN6Jj7\">klubovnách.</a></p>\r\n</div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-calendar-alt text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Termíny akcí​</h3>\r\n<p class=\"fw-light\">Na výlety vyrážíme o víkendech, kurzy a kroužky se konají ve všední dny. ​ <a href=\"https://dobrodruzi.cz/cs/stranka/kontakt\">Zobrazit kalendář</a></p>\r\n</div>\r\n<!-- /.col-lg-4 -->\r\n<div class=\"col-lg-4\">\r\n<p><i class=\"fad fa-hand-holding-heart text-primary\" style=\"font-size: 45px;\"></i></p>\r\n<h3 class=\"fw-bold\">Ceny​</h3>\r\n<p class=\" fw-light\">Dopravu, jídlo a ubytování na výletech si hradí děti sami (výdaje v řádu stokorun). Více informací najdete na stránce ​ <a href=\"https://dobrodruzi.cz/cs/stranka/cenik\">Ceny.</a></p>\r\n</div>\r\n</div>\r\n</div>\r\n</div>\r\n<p></p>\r\n<div class=\"px-4 py-1 my-5 mt-5 text-center\">\r\n<h1 class=\"display-6 fw-bold\">Nyní jsou nejžádanější kurzy programování</h1>\r\n<div class=\"col-lg-6 mx-auto\">\r\n<p class=\"lead mb-4\">Děti učím programovat, vytváříme počítačové hry, a trávíme čas ve zdravém prostředí.</p>\r\n<div class=\"d-grid gap-2 d-sm-flex justify-content-sm-center\"><a href=\"https://dobrodruzi.cz/cs/stranka/kurzy-programovani\" type=\"button\" class=\"btn btn-primary btn-lg px-4 gap-3\">Více o kurzech »</a> <a href=\"https://dobrodruzi.cz/cs/stranka/kontakt\" type=\"button\" class=\"btn btn-outline-secondary btn-lg px-4\">Volné termíny »</a></div>\r\n</div>\r\n</div>', 0, '2026-02-16 16:44:43', '2026-06-11 10:47:42');
INSERT INTO `pages` (`id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(24, 'texty pro lesní školku', 'texty-pro-lesni-skolku', 'zzzzzzzzzzz\r\n<section class=\"my-4 mx-2 mx-lg-4 rounded-4 shadow-lg text-white\" style=\"background: linear-gradient(135deg, #0f2537 0%, #1d4461 100%); overflow: hidden;\">\r\n  <div class=\"container position-relative py-5\">\r\n    <div class=\"row align-items-center g-5 py-3\">\r\n\r\n      <div class=\"col-lg-7 text-center text-lg-start\">\r\n        <div class=\"badge bg-white bg-opacity-20 text-white px-3 py-2 rounded-pill mb-4 fw-semibold border border-white border-opacity-10 shadow-sm\">\r\n          <i class=\"fa-solid fa-seedling me-2 text-warning\"></i>Lesní školka · Jindřichovice pod Smrkem\r\n        </div>\r\n\r\n        <h1 class=\"display-3 fw-bold mb-4 text-white\" style=\"line-height: 1.2; letter-spacing: -1px;\">\r\n          Běháme bosky,<br>\r\n          <span class=\"text-warning\">skáčeme do kaluží.</span>\r\n        </h1>\r\n\r\n        <p class=\"lead mb-5 text-white-50 mx-auto mx-lg-0\" style=\"max-width: 540px; font-size: 1.2rem;\">\r\n          Pravidelné lesní kurzy pro předškolní dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda výchozím bodem — ne cílem.\r\n        </p>\r\n\r\n        <div class=\"d-flex flex-wrap justify-content-center justify-content-lg-start gap-3 mb-5\">\r\n          <a href=\"#prihlaska\" class=\"btn btn-warning btn-lg px-4 py-3 fw-bold text-dark shadow border-0 rounded-3\">\r\n            <i class=\"fa-solid fa-paper-plane me-2\"></i>Zjistit volná místa\r\n          </a>\r\n          <a href=\"#harmonogram\" class=\"btn btn-outline-light btn-lg px-4 py-3 bg-white bg-opacity-10 border-white border-opacity-20 rounded-3\">\r\n            <i class=\"fa-solid fa-arrow-down me-2\"></i>Jak kurzy probíhají\r\n          </a>\r\n        </div>\r\n\r\n        <div class=\"row g-3 text-start\">\r\n          <div class=\"col-4\">\r\n            <div class=\"p-3 bg-white bg-opacity-10 rounded-3 text-center border border-white border-opacity-10\">\r\n              <strong class=\"d-block h2 text-warning fw-bold mb-0\">4+</strong>\r\n              <span class=\"text-white-50 small text-uppercase\" style=\"font-size: 0.75rem; tracking: 0.5px;\">věk dítěte</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"col-4\">\r\n            <div class=\"p-3 bg-white bg-opacity-10 rounded-3 text-center border border-white border-opacity-10\">\r\n              <strong class=\"d-block h2 text-warning fw-bold mb-0\">12</strong>\r\n              <span class=\"text-white-50 small text-uppercase\" style=\"font-size: 0.75rem; tracking: 0.5px;\">max. dětí</span>\r\n            </div>\r\n          </div>\r\n          <div class=\"col-4\">\r\n            <div class=\"p-3 bg-white bg-opacity-10 rounded-3 text-center border border-white border-opacity-10\">\r\n              <strong class=\"d-block h2 text-warning fw-bold mb-0\">80%</strong>\r\n              <span class=\"text-white-50 small text-uppercase\" style=\"font-size: 0.75rem; tracking: 0.5px;\">čas venku</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"col-lg-5\">\r\n        <div class=\"bg-white text-dark p-4 p-md-5 rounded-4 shadow-lg border\">\r\n          <div class=\"text-center mb-3\">\r\n            <span style=\"font-size:2.5rem;\">🏡</span>\r\n          </div>\r\n          <h3 class=\"fw-bold text-primary text-center h4 mb-1\">Základna Svobodného přístavu</h3>\r\n          <p class=\"text-muted text-center small mb-4\">Jindřichovice pod Smrkem 213</p>\r\n\r\n          <div class=\"d-flex flex-column gap-3 mb-4\">\r\n            <div class=\"d-flex align-items-start\">\r\n              <div class=\"text-primary me-3 mt-1 fs-5\"><i class=\"fa-solid fa-house-tree\"></i></div>\r\n              <div>\r\n                <span class=\"d-block fw-bold text-dark small\">Dům, zahrada a les</span>\r\n                <small class=\"text-muted d-block\" style=\"font-size: 0.8rem;\">Bezpečné zázemí + hluboký les přímo za domem</small>\r\n              </div>\r\n            </div>\r\n            <div class=\"d-flex align-items-start border-top pt-2 border-light\">\r\n              <div class=\"text-primary me-3 mt-1 fs-5\"><i class=\"fa-solid fa-heart-circle-check\"></i></div>\r\n              <div>\r\n                <span class=\"d-block fw-bold text-dark small\">Sebeřízené učení</span>\r\n                <small class=\"text-muted d-block\" style=\"font-size: 0.8rem;\">Žádné příkazy — vycházíme z vnitřní motivace dítěte</small>\r\n              </div>\r\n            </div>\r\n            <div class=\"d-flex align-items-start border-top pt-2 border-light\">\r\n              <div class=\"text-primary me-3 mt-1 fs-5\"><i class=\"fa-solid fa-users-between-lines\"></i></div>\r\n              <div>\r\n                <span class=\"d-block fw-bold text-dark small\">Max. 12 dětí</span>\r\n                <small class=\"text-muted d-block\" style=\"font-size: 0.8rem;\">Rodinná atmosféra, každé dítě viditelné</small>\r\n              </div>\r\n            </div>\r\n            <div class=\"d-flex align-items-start border-top pt-2 border-light\">\r\n              <div class=\"text-primary me-3 mt-1 fs-5\"><i class=\"fa-solid fa-clock\"></i></div>\r\n              <div>\r\n                <span class=\"d-block fw-bold text-dark small\">Flexibilní časy</span>\r\n                <small class=\"text-muted d-block\" style=\"font-size: 0.8rem;\">Přizpůsobíme se pracovnímu rytmu vaší rodiny</small>\r\n              </div>\r\n            </div>\r\n          </div>\r\n\r\n          <div class=\"p-3 bg-light rounded-3 text-dark small border-start border-warning border-3\">\r\n            <i class=\"fa-solid fa-lightbulb text-warning me-1\"></i>\r\n            <strong class=\"text-dark\">Pracující rodiče:</strong> <span class=\"text-secondary\">Čas příchodu a odchodu přizpůsobíme vašim potřebám — přijďte dřív, vyzvedněte později.</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-white\" id=\"jak-to-probiha\">\r\n  <div class=\"container py-3\">\r\n    <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 750px;\">\r\n      <span class=\"badge bg-primary bg-opacity-10 text-primary rounded-pill px-3 py-2 mb-3 fw-bold\">Naše filozofie</span>\r\n      <h2 class=\"display-5 fw-bold text-dark mb-3\">Proč lesní školka<br>Malí Dobrodruzi?</h2>\r\n      <p class=\"lead text-muted\">Děti s námi tráví čas přirozeným způsobem — v přírodě, v pohybu, ve svobodě. Příroda nabízí nepřeberné množství podnětů pro rozvoj smyslů, motoriky, kreativity i charakteru.</p>\r\n    </div>\r\n\r\n    <div class=\"row g-4\">\r\n      <div class=\"col-sm-6 col-lg-4\">\r\n        <div class=\"card card-body border-0 bg-light p-4 h-100 rounded-4 position-relative shadow-sm\">\r\n          <span class=\"position-absolute top-0 end-0 m-3 fs-3 fw-bold text-secondary opacity-25\">01</span>\r\n          <div class=\"d-flex align-items-center justify-content-center bg-primary bg-opacity-10 text-primary rounded-3 mb-4\" style=\"width: 50px; height: 50px;\">\r\n            <i class=\"fa-solid fa-tree fs-4\"></i>\r\n          </div>\r\n          <h4 class=\"fw-bold text-dark h5 mb-3\">Příroda jako učebna</h4>\r\n          <p class=\"text-secondary small mb-0\">Většinu času trávíme venku za každého počasí. Les a louka jsou ideálním prostředím pro hry, bádání a přirozený rozvoj. Pokud dítě chce, běhá bosky — to je ta nejlepší senzorická terapie.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-4\">\r\n        <div class=\"card card-body border-0 bg-light p-4 h-100 rounded-4 position-relative shadow-sm\">\r\n          <span class=\"position-absolute top-0 end-0 m-3 fs-3 fw-bold text-secondary opacity-25\">02</span>\r\n          <div class=\"d-flex align-items-center justify-content-center rounded-3 mb-4\" style=\"width: 50px; height: 50px; background-color: #fff8e6; color: #ffc107;\">\r\n            <i class=\"fa-solid fa-hands-holding-child fs-4 text-primary\"></i>\r\n          </div>\r\n          <h4 class=\"fw-bold text-dark h5 mb-3\">Respektující průvodce</h4>\r\n          <p class=\"text-secondary small mb-0\">Jsem pro děti parťák, ne diktátor. Přistupuji k nim individuálně, s respektem a nenásilnou komunikací. Žádné tresty, žádná manipulace — jen upřímný vztah.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-4\">\r\n        <div class=\"card card-body border-0 bg-light p-4 h-100 rounded-4 position-relative shadow-sm\">\r\n          <span class=\"position-absolute top-0 end-0 m-3 fs-3 fw-bold text-secondary opacity-25\">03</span>\r\n          <div class=\"d-flex align-items-center justify-content-center rounded-3 mb-4\" style=\"width: 50px; height: 50px; background-color: #e6f0ff; color: #0d6efd;\">\r\n            <i class=\"fa-solid fa-lightbulb fs-4 text-primary\"></i>\r\n          </div>\r\n          <h4 class=\"fw-bold text-dark h5 mb-3\">Svobodné, sebeřízené učení</h4>\r\n          <p class=\"text-secondary small mb-0\">Využíváme vnitřní motivace dětí. Mohou se věnovat věcem proto, že v nich samy vidí smysl — volná hra i nabízené aktivity jsou rovnocenné. Žádné povinné sezení u stolečku.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-4\">\r\n        <div class=\"card card-body border-0 bg-light p-4 h-100 rounded-4 position-relative shadow-sm\">\r\n          <span class=\"position-absolute top-0 end-0 m-3 fs-3 fw-bold text-secondary opacity-25\">04</span>\r\n          <div class=\"d-flex align-items-center justify-content-center rounded-3 mb-4\" style=\"width: 50px; height: 50px; background-color: #fef0f0; color: #dc3545;\">\r\n            <i class=\"fa-solid fa-virus-slash fs-4 text-primary\"></i>\r\n          </div>\r\n          <h4 class=\"fw-bold text-dark h5 mb-3\">Silná imunita přirozeně</h4>\r\n          <p class=\"text-secondary small mb-0\">Čerstvý vzduch Jizerských hor, pohyb, kontakt s půdou a přírodou — to vše přirozeně posiluje obranyschopnost. Děti v lese málokdy bývají nemocné.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-4\">\r\n        <div class=\"card card-body border-0 bg-light p-4 h-100 rounded-4 position-relative shadow-sm\">\r\n          <span class=\"position-absolute top-0 end-0 m-3 fs-3 fw-bold text-secondary opacity-25\">05</span>\r\n          <div class=\"d-flex align-items-center justify-content-center bg-primary bg-opacity-10 text-primary rounded-3 mb-4\" style=\"width: 50px; height: 50px;\">\r\n            <i class=\"fa-solid fa-shield-heart fs-4\"></i>\r\n          </div>\r\n          <h4 class=\"fw-bold text-dark h5 mb-3\">Maximální psychické bezpečí</h4>\r\n          <p class=\"text-secondary small mb-0\">Malý kolektiv zaručuje rodinnou atmosféru. Žádný pláč v koutě, který nikdo neslyší. Okamžitě reaguji na emoce, potřeby a konflikty — s respektem.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-4\">\r\n        <div class=\"card card-body border-0 bg-light p-4 h-100 rounded-4 position-relative shadow-sm\">\r\n          <span class=\"position-absolute top-0 end-0 m-3 fs-3 fw-bold text-secondary opacity-25\">06</span>\r\n          <div class=\"d-flex align-items-center justify-content-center rounded-3 mb-4\" style=\"width: 50px; height: 50px; background-color: #fff8e6; color: #ffc107;\">\r\n            <i class=\"fa-solid fa-people-group fs-4 text-primary\"></i>\r\n          </div>\r\n          <h4 class=\"fw-bold text-dark h5 mb-3\">Vztahy a týmová spolupráce</h4>\r\n          <p class=\"text-secondary small mb-0\">Děti se učí domluvit, respektovat druhé a být součástí týmu. Rozvíjejí sebedůvěru, férovost a konstruktivní řešení situací — bez trestů a bez direktivy.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 text-white rounded-4 mx-2 mx-lg-4\" style=\"background: linear-gradient(135deg, #0b1a29 0%, #19344d 100%);\">\r\n  <div class=\"container position-relative py-3\">\r\n    <div class=\"text-center mb-5\">\r\n      <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n        <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n        Naše principy\r\n        <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n      </div>\r\n      <h2 class=\"display-5 fw-bold text-white\">Čím se řídíme každý den</h2>\r\n    </div>\r\n\r\n    <div class=\"row g-4 mb-5\">\r\n      <div class=\"col-sm-6 col-lg-3\">\r\n        <div class=\"card card-body bg-white bg-opacity-5 border border-white border-opacity-10 p-4 h-100 rounded-4 text-center text-white\">\r\n          <div class=\"d-flex align-items-center justify-content-center bg-primary bg-opacity-20 text-info rounded-circle mx-auto mb-3\" style=\"width: 55px; height: 55px;\">\r\n            <i class=\"fa-solid fa-dove fs-4\"></i>\r\n          </div>\r\n          <h5 class=\"fw-bold text-white mb-2\">Svoboda</h5>\r\n          <p class=\"text-white-50 small mb-0\">Bez nátlaku, bez manipulace. Každá aktivita stojí na dobrovolnosti a oboustranné dohodě.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-3\">\r\n        <div class=\"card card-body bg-white bg-opacity-5 border border-white border-opacity-10 p-4 h-100 rounded-4 text-center text-white\">\r\n          <div class=\"d-flex align-items-center justify-content-center bg-warning bg-opacity-15 text-info rounded-circle mx-auto mb-3\" style=\"width: 55px; height: 55px;\">\r\n            <i class=\"fa-solid fa-handshake fs-4\"></i>\r\n          </div>\r\n          <h5 class=\"fw-bold text-white mb-2\">Respekt</h5>\r\n          <p class=\"text-white-50 small mb-0\">Dítě není nádoba k naplnění, ale svébytná osobnost. Nasloucháme, neptáme se řečnicky.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-3\">\r\n        <div class=\"card card-body bg-white bg-opacity-5 border border-white border-opacity-10 p-4 h-100 rounded-4 text-center text-white\">\r\n          <div class=\"d-flex align-items-center justify-content-center bg-primary bg-opacity-20 text-info rounded-circle mx-auto mb-3\" style=\"width: 55px; height: 55px;\">\r\n            <i class=\"fa-solid fa-scale-balanced fs-4\"></i>\r\n          </div>\r\n          <h5 class=\"fw-bold text-white mb-2\">Zodpovědnost</h5>\r\n          <p class=\"text-white-50 small mb-0\">Děti se učí nést odpovědnost za svá rozhodnutí. Účel nesvětí prostředky — jednáme férovně.</p>\r\n        </div>\r\n      </div>\r\n      <div class=\"col-sm-6 col-lg-3\">\r\n        <div class=\"card card-body bg-white bg-opacity-5 border border-white border-opacity-10 p-4 h-100 rounded-4 text-center text-white\">\r\n          <div class=\"d-flex align-items-center justify-content-center bg-warning bg-opacity-15 text-info rounded-circle mx-auto mb-3\" style=\"width: 55px; height: 55px;\">\r\n            <i class=\"fa-solid fa-people-arrows fs-4\"></i>\r\n          </div>\r\n          <h5 class=\"fw-bold text-white mb-2\">Spolupráce</h5>\r\n          <p class=\"text-white-50 small mb-0\">Tým je silnější než jednotlivec. Učíme se domluvit, vyslechnout a spolutvořit.</p>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"text-center mx-auto\" style=\"max-width: 850px;\">\r\n      <blockquote class=\"blockquote fs-4 fst-italic text-info my-4\">\r\n        „Nejdůležitější je atmosféra — místo, kde děti mohou být stoprocentně samy sebou, svobodně prozkoumávat svět, zašpinit se od bláta a cítit, že jsou bezpodmínečně přijímány takové, jaké jsou.\"\r\n      </blockquote>\r\n      <p class=\"text-white-50 small mt-2\">— Petr Lízal (AG), průvodce</p>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-white\" id=\"pruvodce\">\r\n  <div class=\"container py-3\">\r\n    <div class=\"row align-items-center g-5\">\r\n\r\n      <div class=\"col-lg-4 text-center\">\r\n        <div class=\"rounded-circle mx-auto border border-4 border-light shadow-lg mb-4 bg-light\" style=\"width: 240px; height: 240px; overflow: hidden;\">\r\n          <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\" class=\"w-100 h-100\" style=\"object-fit: cover;\">\r\n        </div>\r\n        <h4 class=\"fw-bold text-dark mb-1\" style=\"font-size: 1.6rem;\">Petr Lízal</h4>\r\n        <p class=\"text-muted small mb-3\">Přezdívka: <strong>AG (Ejdží)</strong> · 37 let</p>\r\n        <div class=\"d-flex flex-wrap justify-content-center gap-2\">\r\n          <span class=\"badge bg-primary bg-opacity-10 text-primary px-3 py-2 rounded-pill small fw-medium\">🌲 Průvodce</span>\r\n          <span class=\"badge bg-primary bg-opacity-10 text-primary px-3 py-2 rounded-pill small fw-medium\">🧗 Lektor</span>\r\n          <span class=\"badge bg-primary bg-opacity-10 text-primary px-3 py-2 rounded-pill small fw-medium\">🌍 Cestovatel</span>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"col-lg-8 text-start\">\r\n        <span class=\"text-primary small fw-bold text-uppercase tracking-wider d-block mb-1\">Váš průvodce</span>\r\n        <h2 class=\"display-5 fw-bold text-dark mb-4\">„Jsem pro děti parťák,<br>nikoli diktátor.\"</h2>\r\n\r\n        <p class=\"text-secondary mb-3\" style=\"line-height: 1.75;\">\r\n          Odmala miluji dobrodružství a cestování. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye — a právě tam se ze mě stal skutečný dobrodruh. Více než 20 let jsem průvodcem a lektorem pro děti, organizoval jsem stovky výletů a desítky skautských táborů.\r\n        </p>\r\n        <p class=\"text-secondary mb-4\" style=\"line-height: 1.75;\">\r\n          Ovlivnily mě knihy jako <em>Respektovat a být respektován</em>, <em>Nenásilná komunikace</em> nebo <em>Summerhill</em>. Pochopil jsem, že děti nepotřebují autoritu postavenou na strachu — ale bezpečné hranice, bezmeznou důvěru a dospělého jako rovnocenného parťáka.\r\n        </p>\r\n\r\n        <div class=\"d-flex flex-column gap-2 text-dark small\">\r\n          <div class=\"d-flex align-items-center text-dark\"><i class=\"fa-solid fa-graduation-cap text-primary me-3 fs-5\" style=\"width: 24px;\"></i> <span>20+ let praxe s dětskými kolektivy</span></div>\r\n          <div class=\"d-flex align-items-center text-dark\"><i class=\"fa-solid fa-campground text-primary me-3 fs-5\" style=\"width: 24px;\"></i> <span>Desítky zorganizovaných skautských táborů a kurzů</span></div>\r\n          <div class=\"d-flex align-items-center text-dark\"><i class=\"fa-solid fa-school text-primary me-3 fs-5\" style=\"width: 24px;\"></i> <span>Zkušenost z inovativní svobodné školy</span></div>\r\n          <div class=\"d-flex align-items-center text-dark\"><i class=\"fa-solid fa-earth-americas text-primary me-3 fs-5\" style=\"width: 24px;\"></i> <span>Expediční zkušenosti z Jižní Ameriky i dalšího zahraničí</span></div>\r\n          <div class=\"d-flex align-items-center text-dark\"><i class=\"fa-solid fa-book-open text-primary me-3 fs-5\" style=\"width: 24px;\"></i> <span>NVC, sebeřízené vzdělávání, respektující přístup v praxi</span></div>\r\n        </div>\r\n      </div>\r\n      \r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light rounded-4 mx-2 mx-lg-4\" id=\"harmonogram\">\r\n  <div class=\"container py-3\">\r\n    <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 750px;\">\r\n      <span class=\"badge bg-primary bg-opacity-10 text-primary rounded-pill px-3 py-2 mb-3 fw-bold\">Jak den probíhá</span>\r\n      <h2 class=\"display-5 fw-bold text-dark mb-3\">Harmonogram a rituály</h2>\r\n      <p class=\"lead text-muted\">Pravidelný řád dává dětem pocit jistoty a bezpečí. Orientují se v čase právě díky opakování rituálů — ale tempo vždy přizpůsobujeme energii skupiny.</p>\r\n    </div>\r\n\r\n    <div class=\"d-flex justify-content-center mb-4\">\r\n      <ul class=\"nav nav-pills bg-white p-2 rounded-pill shadow-sm gap-1 flex-wrap justify-content-center border\" id=\"scheduleTabs\" role=\"tablist\">\r\n        <li class=\"nav-item\" role=\"presentation\">\r\n          <button class=\"nav-link active rounded-pill px-3 py-2 fw-semibold\" id=\"tab-regular\" data-bs-toggle=\"tab\" data-bs-target=\"#panel-regular\" type=\"button\" role=\"tab\">\r\n            <i class=\"fa-solid fa-sun me-1\"></i> Pravidelné kurzy\r\n          </button>\r\n        </li>\r\n        <li class=\"nav-item\" role=\"presentation\">\r\n          <button class=\"nav-link rounded-pill px-3 py-2 fw-semibold\" id=\"tab-morning\" data-bs-toggle=\"tab\" data-bs-target=\"#panel-morning\" type=\"button\" role=\"tab\">\r\n            <i class=\"fa-solid fa-mug-hot me-1\"></i> Dopolední (víkend)\r\n          </button>\r\n        </li>\r\n        <li class=\"nav-item\" role=\"presentation\">\r\n          <button class=\"nav-link rounded-pill px-3 py-2 fw-semibold\" id=\"tab-afternoon\" data-bs-toggle=\"tab\" data-bs-target=\"#panel-afternoon\" type=\"button\" role=\"tab\">\r\n            <i class=\"fa-solid fa-moon me-1\"></i> Odpolední (všední)\r\n          </button>\r\n        </li>\r\n      </ul>\r\n    </div>\r\n\r\n    <div class=\"tab-content\" id=\"scheduleTabContent\">\r\n\r\n      <div class=\"tab-pane fade show active\" id=\"panel-regular\" role=\"tabpanel\">\r\n        <div class=\"row justify-content-center\">\r\n          <div class=\"col-lg-9\">\r\n            <div class=\"d-flex flex-column gap-2 bg-white p-3 p-md-4 rounded-4 border shadow-sm text-start\">\r\n              <div class=\"row align-items-center p-3 rounded-3 bg-primary bg-opacity-10 g-2 text-dark\">\r\n                <div class=\"col-12 col-sm-2 text-primary fw-bold fs-5\">před 9:00</div>\r\n                <div class=\"col-2 col-sm-1 text-center text-muted fs-4 d-none d-sm-block\"><i class=\"fa-solid fa-door-open text-primary\"></i></div>\r\n                <div class=\"col-10 col-sm-9 text-dark\"><strong class=\"d-block text-dark small mb-1 text-uppercase fw-bold\">Možnost dřívějšího příchodu</strong><span class=\"text-secondary small\">Klidové aktivity na základně dle potřeb rodičů</span></div>\r\n              </div>\r\n              <div class=\"row align-items-center p-3 rounded-3 g-2 border-top border-light text-dark\">\r\n                <div class=\"col-12 col-sm-2 text-primary fw-bold fs-5\">9:00</div>\r\n                <div class=\"col-2 col-sm-1 text-center text-muted fs-4 d-none d-sm-block\"><i class=\"fa-solid fa-circle-nodes text-primary\"></i></div>\r\n                <div class=\"col-10 col-sm-9 text-dark\"><strong class=\"d-block text-dark small mb-1 text-uppercase fw-bold\">Poradní kruh</strong><span class=\"text-secondary small\">Přivítání, plánování dne, přání dětí, reflexe</span></div>\r\n              </div>\r\n              <div class=\"row align-items-center p-3 rounded-3 g-2 border-top border-light text-dark\">\r\n                <div class=\"col-12 col-sm-2 text-primary fw-bold fs-5\">9:30 – 12:00</div>\r\n                <div class=\"col-2 col-sm-1 text-center text-muted fs-4 d-none d-sm-block\"><i class=\"fa-solid fa-tree text-primary\"></i></div>\r\n                <div class=\"col-10 col-sm-9 text-dark\"><strong class=\"d-block text-dark small mb-1 text-uppercase fw-bold\">Expedice do lesa</strong><span class=\"text-secondary small\">Řízené i volné hry, poznávání přírody, bádání, pohyb</span></div>\r\n              </div>\r\n              <div class=\"row align-items-center p-3 rounded-3 g-2 border-top border-light text-dark\">\r\n                <div class=\"col-12 col-sm-2 text-primary fw-bold fs-5\">12:00</div>\r\n                <div class=\"col-2 col-sm-1 text-center text-muted fs-4 d-none d-sm-block\"><i class=\"fa-solid fa-bowl-food text-primary\"></i></div>\r\n                <div class=\"col-10 col-sm-9 text-dark\"><strong class=\"d-block text-dark small mb-1 text-uppercase fw-b