(200, 22, 'Sebeřízené vzdělávání', 'home', '[hlavicka typ=\"hero_default\" title1=\"Putujeme přírodou a učíme se novým dovednostem\" text1=\"Provázím mladé dobrodruhy na cestách za poznáním\" img1=\"/img/slideohen.jpg\" title2=\"Nabízím zážitky na celý život\" text2=\"výlety I expedice I vzdělávací kurzy\" img2=\"/img/slidelod.jpg\" title3=\"Vytvářím pro děti příležitosti k seberozvoji\" text3=\"A trávíme čas ve zdravém prostředí\" img3=\"/img/slidealex.jpg\"]\r\n\r\n[blok typ=\"blok_nadpis1\" podnadpis=\"Dobrodruzi.cz\" nadpis=\"Sebeřízené vzdělávání\" text=\"Vytvářím pro děti z Jindřichovic pod Smrkem <strong>příležitosti</strong> k všestrannému rozvoji, pořádám výlety, expedice, kurzy, kroužky, věnujeme se vzdělávání, praktickým dovednostem, a dalším volnočasovým aktivitám a hrám.\"]\r\n\r\n[blok typ=\"blok_uvod\" nadpis=\"Putujeme přírodou a učíme se novým dovednostem\" text1=\"S dětmi zkoumám svět, bádáme, učíme se a hrajeme si, se staršími dobrodruhy společně plánujeme a uskutečňujeme velká dobrodružství.\" text2=\"Na cestách najdou vaše děti nové přátele a zažijí spoustu zábavy a dobrodružství.\" odkaz_url=\"https://dobrodruzi.cz/cs/stranka/vylety\" odkaz_ikona=\"fa-solid fa-person-hiking\" odkaz_text=\"Výlety do přírody\" obrazek_src=\"/img/obr5.jpg\" obrazek_alt=\"Děti putující přírodou\"]\r\n\r\n\r\n[blok typ=\"blok_nadpis2\" nadpis=\"Víc než jen zábava\" text=\"Na výletech a kurzech děti rozvíjejí sebedůvěru, samostatnost, férovost, spolupráci. Učí se žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.\"]\r\n\r\n\r\n[blok typ=\"blok_karty3\" ikona1=\"fa-solid fa-person-hiking\" nadpis1=\"Výlety\" text1=\"Cestovatelské a tábornické znalosti, dovednosti přežití. Zkušený průvodce, respektující přístup a spousta zábavy.\" ikona2=\"fa-solid fa-users\" nadpis2=\"Kroužky\" text2=\"Většinu času trávíme v pohybu, v přírodě, za každého počasí. Věnujeme se, pohybovým hrám a vzdělávacím činnostem.\" ikona3=\"fa-solid fa-campground\" nadpis3=\"Kurzy\" text3=\"Nabízím vzdělávací činnosti, výuku programování, sjíždění řek na nafukovacích kánojích, cestovatelské dovednosti a znalosti.\"]\r\n\r\n[blok typ=\"blok_knihy\" obrazek_src=\"/img/knihy.png\" obrazek_alt=\"Respektující literatura\" podnadpis=\"Knihy, ze kterých vycházím\" nadpis=\"Respekt, svoboda, zodpovědnost​\" text=\"Klíčem ke spokojenému životu jsou dobré mezilidské vztahy, ty představují zdroj většiny radostí i bolestí v lidském životě. Mladí dobrodruzi pěstují vztahy založené na vzájemném respektu a úctě.​\" tlacitko1_url=\"https://www.peoplecomm.cz/respektovat-a-byt-respektovan\" tlacitko1_text=\"Respektovat a být res.\" tlacitko2_url=\"https://www.peoplecomm.cz/kniha-summerhill\" tlacitko2_text=\"Demokratická škola\" tlacitko3_url=\"https://www.peoplecomm.cz/svoboda-uceni\" tlacitko3_text=\"​​Svoboda učení\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_nadpis3\" nadpis=\"Dávám možnost říct <span class=\'text-info\'>„ne“</span>\" text=\"Ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a potřeb, následně společně tvoříme přijatelná řešení. Akceptuji volbu a přirozené následky.\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_karty2\" ikona1=\"fa-solid fa-arrows-alt\" nadpis1=\"Připravuji řízený program formou nabídky\" text1=\"Využívám <strong>vnitřní motivace</strong> dětí, aby se mohly věnovat věcem proto, že v nich vidí <strong>smysl</strong>, že je baví a že samy chtějí.\" ikona2=\"fa-solid fa-handshake-angle\" nadpis2=\"„Jsem pro děti parťák, nikoli diktátor“\" text2=\"Děti vedu k samostatnosti, přistupuji k nim individuálně a s <strong>respektem</strong>. Zajišťuji bezpečné a motivující prostředí, ve kterém se mohou všestranně rozvíjet. Dávám jim prostor pro volnou hru a svobodné učení.\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_obrazky_texty\" podnadpis=\"Bezpečný rozvoj\" nadpis=\"Učíme se prostřednictvím přírody\" text_uvod=\"Volnočasové aktivity organizuji převážně v přírodě, protože pobyt venku a pohyb na čerstvém vzduchu podporuje zdraví a odolnost dětí. Děti poznávají okolí místa, kde žijí, osvojují si praktické cestovatelské dovednosti a učí se rozpoznat přirozená nebezpečí.\" obr1_src=\"/img/sm-b1.jpg\" obr1_alt=\"Děti v kolektivu\" text1=\"Děti se učí žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.\" obr2_src=\"/img/sm-b4.jpg\" obr2_alt=\"Kreativita dětí\" text2=\"Vytvářejí si pozitivní vztah sami k sobě, a neustále na sobě pracují. Podporujeme jejich kreativitu a zručnost.\" obr3_src=\"/img/sm-b2.jpg\" obr3_alt=\"Rituály a přátelství\" text3=\"Poznávají hodnotu přátelství a sdílení, prožívají společně rituály. Osvojují si správné řešení konfliktů a efektivní komunikaci.\"]\r\n\r\n\r\n\r\n\r\n[blok typ=\"blok_info_karty\" ikona1=\"fa-solid fa-map-location-dot\" nadpis1=\"Místa konání\" text1=\"Scházíme se v Jindřichovicích pod Smrkem, nejlepší učebna je sama příroda, v létě i v zimě využíváme zázemí <a href=\'https://goo.gl/maps/itTNU4573LkMN6Jj7\' target=\'_blank\' class=\'text-info fw-semibold text-decoration-none\'>základny</a> Svobodům.\" odkaz1_url=\"https://goo.gl/maps/itTNU4573LkMN6Jj7\" odkaz1_text=\"Zobrazit mapu\" ikona2=\"fa-solid fa-calendar-days\" nadpis2=\"Termíny akcí\" text2=\"Na výlety vyrážíme o víkendech, kurzy a kroužky se konají ve všední dny.\" odkaz2_url=\"https://dobrodruzi.cz/rezervace/\" odkaz2_text=\"Zobrazit kalendář\" ikona3=\"fa-solid fa-hand-holding-heart\" nadpis3=\"Ceny\" text3=\"Dopravu, jídlo a ubytování na výletech si hradí děti sami (výdaje v řádu stokorun). Více informací najdete na stránce cen.\" odkaz3_url=\"https://dobrodruzi.cz/cs/stranka/cenik\" odkaz3_text=\"Přejít na Ceny\"]\r\n\r\n\r\n\r\n\r\n[blok typ=\"blok_kurzy_prog\" ikona=\"fa-solid fa-laptop-code\" nadpis=\"Nyní jsou nejžádanější kurzy programování\" text=\"Děti učím programovat, vytváříme počítačové hry, a trávíme čas ve zdravém prostředí.\" odkaz1_url=\"https://dobrodruzi.cz/cs/stranka/kurzy-programovani\" odkaz1_text=\"Více o kurzech »\" odkaz2_url=\"https://dobrodruzi.cz/rezervace/\" odkaz2_text=\"Volné termíny »\"]\r\n\r\n\r\n [blok typ=\"split_feature\" badge=\"Technika venku\" title=\"Píšeme programátorský kód přímo v přírodě\" text=\"Kdo říká, že technologie patří jen do tmavých pokojů? Naše expedice kombinují pobyt na čerstvém vzduchu s rozvojem logického myšlení.\" img=\"/img/uploads/41/b20.jpg\" list1=\"Respektující přístup a práce vlastním tempem\" list2=\"Spojení moderních technologií a pobytu venku\" list3=\"Řešení reálných technických problémů\" btn_text=\"Prohlédnout aktivity\" btn_link=\"/aktivity\"]', 1, '2026-06-13 13:27:42', '2026-06-13 13:27:42'),
(201, 4, 'O mne', 'o-mne', '[hlavicka typ=\"hero_banner\" title=\"Příroda je nejlepší učebna\" text=\"Výlety I Expedice I Vzdělávací kurzy I Kroužky\" img=\"/img/slidelod.jpg\" overlay=\"0.3\"]\r\n\r\n<section class=\"py-5 mt-4\">\r\n    <div class=\"container py-3 text-center\">\r\n        <h1 class=\"display-5 fw-bold text-dark mb-4\">Něco málo o mně</h1>\r\n        <div class=\"row justify-content-center\">\r\n            <div class=\"col-12 col-md-10 col-lg-8\">\r\n                <p class=\"lead text-muted mb-0\">\r\n                    Jsem zkušený cestovatel a průvodce dětí. Rozumím respektující výchově dětí, mám nápady jak udělat\r\n                    dětem ze života radost a příležitost k seberozvoji.​​\r\n                </p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom rounded-4 mx-2 mx-lg-4 my-4 shadow-sm\">\r\n    <div class=\"container py-4\">\r\n        <div class=\"row flex-lg-row-reverse align-items-center g-5\">\r\n\r\n            <div class=\"col-12 col-lg-6 text-center\">\r\n                <div\r\n                    class=\"position-relative p-2 bg-white rounded-4 shadow-sm border border-info border-opacity-10 d-inline-block\">\r\n                    <img src=\"/img/ja4.jpg\" class=\"img-fluid rounded-4 shadow-sm\" alt=\"Petr Lízal\" loading=\"lazy\"\r\n                        style=\"object-fit: cover; max-width: 100%;\">\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-12 col-lg-6 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Můj příběh\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                <h4 class=\"display-6 fw-bold text-dark mb-4\" style=\"line-height: 1.2;\">Něco málo o mně</h4>\r\n\r\n                <div>\r\n                    <p class=\"fw-light mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo\r\n                        odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do\r\n                        neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam\r\n                        se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek,\r\n                        stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti.\r\n                        Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let\r\n                        předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace,\r\n                        Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad\r\n                        sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Nejdůležitější je pro mě atmosféra — místo, kde děti mohou být\r\n                        samy sebou, svobodně objevovat svět a cítit, že jsou přijímány takové, jaké jsou.</p>\r\n\r\n                    <p class=\"fw-light mb-0\">Na Svobodomě vytvářím právě takový prostor. Bez nátlaku, bez\r\n                        manipulace a bez plánů narýsovaných shora. Jen s respektem, důvěrou a lidskostí.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center\">\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-gears fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Svoboda a zodpovědnost</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Jsem přesvědčen, že si každý o svém životě dokáže nejlépe rozhodovat sám. Všechny svobodné děti\r\n                        se rády učí už od přírody, není je potřeba nutit a brát jim jejich zodpovědnost za svůj život.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-people-arrows fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respekt, účel nesvětí prostředky</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Považuji za správné nikoho k ničemu násilím nenutit, dokud si dotyčný hledí svého a nijak útokem\r\n                        neubližuje druhým; a ani když si zásah vůči němu většina demokraticky odhlasuje, neudělá to ze\r\n                        zlé věci dobrou.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-arrows-alt fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dobrovolnost a volba</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Rozumím respektující výchově, ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a\r\n                        potřeb, následně společně tvoříme přijatelná řešení.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-5 justify-content-center\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Kamarádi </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-campground text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dobrodružství </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-tree text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Pobyt v přírodě </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-compass text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dovednosti </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-handshake text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Respekt </h5>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-4 text-center\">\r\n        <h1 class=\"display-6 fw-bold text-dark mb-3\">Zaplatit profesionála se vyplatí</h1>\r\n        <div class=\"row justify-content-center mb-5\">\r\n            <div class=\"col-12 col-md-8 col-lg-6\">\r\n                <p class=\"lead mb-0\">Nabízím na prvním místě bezpečné motivující prostředí.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-left-right fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">„Průvodci jsou pro děti partneři, ne diktátoři“</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Výjimečnost <i class=\"fa-solid fa-fire text-info mx-1\"></i><span\r\n                            class=\"text-info fw-bold\">dobrodruzi.cz</span> spočívá ve spolupráci s profesionálními\r\n                        průvodci, kteří jsou nejen zkušenými cestovateli, ale rozumí i respektující výchově. Právě to je\r\n                        velká výhoda oproti jiným dobrovolnickým organizacím, protože v nich často působí mladí lidé,\r\n                        kteří nemají dostatečné znalosti a zkušenosti. Né nadarmo se říká, levné věci jsou drahé.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-holding-heart fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Dvacet let jako dobrovolník</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Věnoval jsem dětem již tisíce hodin a statisíce korun ze své kapsy. Jako každý člověk mám ve\r\n                        svém životě <strong>omezený zdroj času, rád daruji část svého</strong>, přesto další část musím\r\n                        investovat do práce která mě uživí.​ Nabízím dětem placené kurzy, výlety, kroužky, je to práce\r\n                        jako každá jiná.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light text-black rounded-4 my-4 text-center\">\r\n    <div class=\"container py-4\">\r\n        <h1 class=\"display-5 fw-bold text-black mb-4\">Směna je užitečná</h1>\r\n        <div class=\"row justify-content-center\">\r\n            <div class=\"col-12 col-md-10 col-lg-8\">\r\n                <p class=\"lead mb-5\">\r\n                    Už od počátku věků si lidé vyměňují užitečné služby skrze peníze, zkrátka protože je to <strong>pro\r\n                        obě strany výhodné</strong> a mají z toho <strong>užitek</strong>.\r\n                </p>\r\n                <div class=\"d-grid gap-2 d-sm-flex justify-content-sm-center\">\r\n                    <a class=\"btn btn-info text-dark fw-bold btn-lg px-4 rounded-3 shadow-sm\"\r\n                        href=\"https://dobrodruzi.cz/rezervace/\">\r\n                        Objednat průvodce\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Nabízím profesionální služby pro děti</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Velkým dobrodruhům pomáhám uskutečnit náročné expedice, naopak mladším rád uspořádám dobrodružný\r\n                        výlet na míru. V nabídce mám nejrůznější kurzy, během roku pořádám různorodé kroužky.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-sparkles fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Tvořím pro děti příležitosti k osobnímu rozvoji</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Činnost pro děti tvořím tam, kde je o to zájem, proto mne neváhejte kontaktovat. Mohu stvořit\r\n                        kroužek pro Vaše mladé dobrodruhy <strong>i v místě Vašeho bydliště</strong>.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>', 1, '2026-06-13 13:34:43', '2026-06-13 13:34:43');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(202, 4, 'O mne', 'o-mne', '[hlavicka typ=\"hero_banner\" title=\"Příroda je nejlepší učebna\" text=\"Výlety I Expedice I Vzdělávací kurzy I Kroužky\" img=\"/img/slidelod.jpg\" overlay=\"0.3\"]\r\n\r\n\r\n[blok typ=\"blok_nadpis2\" nadpis=\"Něco málo o mně\" text=\" Jsem zkušený cestovatel a průvodce dětí. Rozumím respektující výchově dětí, mám nápady jak udělat\r\n                    dětem ze života radost a příležitost k seberozvoji.\"]\r\n\r\n<section class=\"py-5 mt-4\">\r\n    <div class=\"container py-3 text-center\">\r\n        <h1 class=\"display-5 fw-bold text-dark mb-4\">Něco málo o mně</h1>\r\n        <div class=\"row justify-content-center\">\r\n            <div class=\"col-12 col-md-10 col-lg-8\">\r\n                <p class=\"lead text-muted mb-0\">\r\n                    Jsem zkušený cestovatel a průvodce dětí. Rozumím respektující výchově dětí, mám nápady jak udělat\r\n                    dětem ze života radost a příležitost k seberozvoji.​​\r\n                </p>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom rounded-4 mx-2 mx-lg-4 my-4 shadow-sm\">\r\n    <div class=\"container py-4\">\r\n        <div class=\"row flex-lg-row-reverse align-items-center g-5\">\r\n\r\n            <div class=\"col-12 col-lg-6 text-center\">\r\n                <div\r\n                    class=\"position-relative p-2 bg-white rounded-4 shadow-sm border border-info border-opacity-10 d-inline-block\">\r\n                    <img src=\"/img/ja4.jpg\" class=\"img-fluid rounded-4 shadow-sm\" alt=\"Petr Lízal\" loading=\"lazy\"\r\n                        style=\"object-fit: cover; max-width: 100%;\">\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-12 col-lg-6 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Můj příběh\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                <h4 class=\"display-6 fw-bold text-dark mb-4\" style=\"line-height: 1.2;\">Něco málo o mně</h4>\r\n\r\n                <div>\r\n                    <p class=\"fw-light mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo\r\n                        odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do\r\n                        neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam\r\n                        se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek,\r\n                        stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti.\r\n                        Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let\r\n                        předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace,\r\n                        Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad\r\n                        sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Nejdůležitější je pro mě atmosféra — místo, kde děti mohou být\r\n                        samy sebou, svobodně objevovat svět a cítit, že jsou přijímány takové, jaké jsou.</p>\r\n\r\n                    <p class=\"fw-light mb-0\">Na Svobodomě vytvářím právě takový prostor. Bez nátlaku, bez\r\n                        manipulace a bez plánů narýsovaných shora. Jen s respektem, důvěrou a lidskostí.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center\">\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-gears fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Svoboda a zodpovědnost</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Jsem přesvědčen, že si každý o svém životě dokáže nejlépe rozhodovat sám. Všechny svobodné děti\r\n                        se rády učí už od přírody, není je potřeba nutit a brát jim jejich zodpovědnost za svůj život.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-people-arrows fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respekt, účel nesvětí prostředky</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Považuji za správné nikoho k ničemu násilím nenutit, dokud si dotyčný hledí svého a nijak útokem\r\n                        neubližuje druhým; a ani když si zásah vůči němu většina demokraticky odhlasuje, neudělá to ze\r\n                        zlé věci dobrou.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-arrows-alt fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dobrovolnost a volba</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Rozumím respektující výchově, ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a\r\n                        potřeb, následně společně tvoříme přijatelná řešení.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-5 justify-content-center\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Kamarádi </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-campground text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dobrodružství </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-tree text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Pobyt v přírodě </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-compass text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dovednosti </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-handshake text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Respekt </h5>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-4 text-center\">\r\n        <h1 class=\"display-6 fw-bold text-dark mb-3\">Zaplatit profesionála se vyplatí</h1>\r\n        <div class=\"row justify-content-center mb-5\">\r\n            <div class=\"col-12 col-md-8 col-lg-6\">\r\n                <p class=\"lead mb-0\">Nabízím na prvním místě bezpečné motivující prostředí.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-left-right fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">„Průvodci jsou pro děti partneři, ne diktátoři“</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Výjimečnost <i class=\"fa-solid fa-fire text-info mx-1\"></i><span\r\n                            class=\"text-info fw-bold\">dobrodruzi.cz</span> spočívá ve spolupráci s profesionálními\r\n                        průvodci, kteří jsou nejen zkušenými cestovateli, ale rozumí i respektující výchově. Právě to je\r\n                        velká výhoda oproti jiným dobrovolnickým organizacím, protože v nich často působí mladí lidé,\r\n                        kteří nemají dostatečné znalosti a zkušenosti. Né nadarmo se říká, levné věci jsou drahé.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-holding-heart fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Dvacet let jako dobrovolník</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Věnoval jsem dětem již tisíce hodin a statisíce korun ze své kapsy. Jako každý člověk mám ve\r\n                        svém životě <strong>omezený zdroj času, rád daruji část svého</strong>, přesto další část musím\r\n                        investovat do práce která mě uživí.​ Nabízím dětem placené kurzy, výlety, kroužky, je to práce\r\n                        jako každá jiná.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light text-black rounded-4 my-4 text-center\">\r\n    <div class=\"container py-4\">\r\n        <h1 class=\"display-5 fw-bold text-black mb-4\">Směna je užitečná</h1>\r\n        <div class=\"row justify-content-center\">\r\n            <div class=\"col-12 col-md-10 col-lg-8\">\r\n                <p class=\"lead mb-5\">\r\n                    Už od počátku věků si lidé vyměňují užitečné služby skrze peníze, zkrátka protože je to <strong>pro\r\n                        obě strany výhodné</strong> a mají z toho <strong>užitek</strong>.\r\n                </p>\r\n                <div class=\"d-grid gap-2 d-sm-flex justify-content-sm-center\">\r\n                    <a class=\"btn btn-info text-dark fw-bold btn-lg px-4 rounded-3 shadow-sm\"\r\n                        href=\"https://dobrodruzi.cz/rezervace/\">\r\n                        Objednat průvodce\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Nabízím profesionální služby pro děti</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Velkým dobrodruhům pomáhám uskutečnit náročné expedice, naopak mladším rád uspořádám dobrodružný\r\n                        výlet na míru. V nabídce mám nejrůznější kurzy, během roku pořádám různorodé kroužky.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-sparkles fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Tvořím pro děti příležitosti k osobnímu rozvoji</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Činnost pro děti tvořím tam, kde je o to zájem, proto mne neváhejte kontaktovat. Mohu stvořit\r\n                        kroužek pro Vaše mladé dobrodruhy <strong>i v místě Vašeho bydliště</strong>.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>', 1, '2026-06-13 13:35:08', '2026-06-13 13:35:08'),
(203, 4, 'O mne', 'o-mne', '[hlavicka typ=\"hero_banner\" title=\"Příroda je nejlepší učebna\" text=\"Výlety I Expedice I Vzdělávací kurzy I Kroužky\" img=\"/img/slidelod.jpg\" overlay=\"0.3\"]\r\n\r\n\r\n[blok typ=\"blok_nadpis2\" nadpis=\"Něco málo o mne\" text=\" Jsem zkušený cestovatel a průvodce dětí. Rozumím respektující výchově dětí, mám nápady jak udělat\r\n                    dětem ze života radost a příležitost k seberozvoji.\"]\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom rounded-4 mx-2 mx-lg-4 my-4 shadow-sm\">\r\n    <div class=\"container py-4\">\r\n        <div class=\"row flex-lg-row-reverse align-items-center g-5\">\r\n\r\n            <div class=\"col-12 col-lg-6 text-center\">\r\n                <div\r\n                    class=\"position-relative p-2 bg-white rounded-4 shadow-sm border border-info border-opacity-10 d-inline-block\">\r\n                    <img src=\"/img/ja4.jpg\" class=\"img-fluid rounded-4 shadow-sm\" alt=\"Petr Lízal\" loading=\"lazy\"\r\n                        style=\"object-fit: cover; max-width: 100%;\">\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-12 col-lg-6 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Můj příběh\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                <h4 class=\"display-6 fw-bold text-dark mb-4\" style=\"line-height: 1.2;\">Něco málo o mně</h4>\r\n\r\n                <div>\r\n                    <p class=\"fw-light mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo\r\n                        odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do\r\n                        neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam\r\n                        se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek,\r\n                        stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti.\r\n                        Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let\r\n                        předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace,\r\n                        Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad\r\n                        sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n\r\n                    <p class=\"fw-light mb-3\">Nejdůležitější je pro mě atmosféra — místo, kde děti mohou být\r\n                        samy sebou, svobodně objevovat svět a cítit, že jsou přijímány takové, jaké jsou.</p>\r\n\r\n                    <p class=\"fw-light mb-0\">Na Svobodomě vytvářím právě takový prostor. Bez nátlaku, bez\r\n                        manipulace a bez plánů narýsovaných shora. Jen s respektem, důvěrou a lidskostí.</p>\r\n                </div>\r\n\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center\">\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-gears fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Svoboda a zodpovědnost</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Jsem přesvědčen, že si každý o svém životě dokáže nejlépe rozhodovat sám. Všechny svobodné děti\r\n                        se rády učí už od přírody, není je potřeba nutit a brát jim jejich zodpovědnost za svůj život.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-people-arrows fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respekt, účel nesvětí prostředky</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Považuji za správné nikoho k ničemu násilím nenutit, dokud si dotyčný hledí svého a nijak útokem\r\n                        neubližuje druhým; a ani když si zásah vůči němu většina demokraticky odhlasuje, neudělá to ze\r\n                        zlé věci dobrou.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-xl-5 rounded-4 text-start shadow-sm d-flex flex-column\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 70px; height: 70px;\">\r\n                        <i class=\"fa-solid fa-arrows-alt fs-3\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dobrovolnost a volba</h5>\r\n                    <p class=\"fw-light mb-0 flex-grow-1\">\r\n                        Rozumím respektující výchově, ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a\r\n                        potřeb, následně společně tvoříme přijatelná řešení.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\">\r\n    <div class=\"container px-4\">\r\n        <div class=\"row g-3 g-lg-4 row-cols-2 row-cols-md-3 row-cols-lg-5 justify-content-center\">\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-users text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Kamarádi </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-campground text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dobrodružství </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-tree text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Pobyt v přírodě </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-compass text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Dovednosti </h5>\r\n                </div>\r\n            </div>\r\n            \r\n            <div class=\"col\">\r\n                <div class=\"card-responsive text-center border-0\">\r\n                    <i class=\"fa-solid fa-handshake text-info fs-1 mb-3 mx-auto d-block\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-0 fs-6\">Respekt </h5>\r\n                </div>\r\n            </div>\r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-4 text-center\">\r\n        <h1 class=\"display-6 fw-bold text-dark mb-3\">Zaplatit profesionála se vyplatí</h1>\r\n        <div class=\"row justify-content-center mb-5\">\r\n            <div class=\"col-12 col-md-8 col-lg-6\">\r\n                <p class=\"lead mb-0\">Nabízím na prvním místě bezpečné motivující prostředí.</p>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-left-right fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">„Průvodci jsou pro děti partneři, ne diktátoři“</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Výjimečnost <i class=\"fa-solid fa-fire text-info mx-1\"></i><span\r\n                            class=\"text-info fw-bold\">dobrodruzi.cz</span> spočívá ve spolupráci s profesionálními\r\n                        průvodci, kteří jsou nejen zkušenými cestovateli, ale rozumí i respektující výchově. Právě to je\r\n                        velká výhoda oproti jiným dobrovolnickým organizacím, protože v nich často působí mladí lidé,\r\n                        kteří nemají dostatečné znalosti a zkušenosti. Né nadarmo se říká, levné věci jsou drahé.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-holding-heart fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Dvacet let jako dobrovolník</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Věnoval jsem dětem již tisíce hodin a statisíce korun ze své kapsy. Jako každý člověk mám ve\r\n                        svém životě <strong>omezený zdroj času, rád daruji část svého</strong>, přesto další část musím\r\n                        investovat do práce která mě uživí.​ Nabízím dětem placené kurzy, výlety, kroužky, je to práce\r\n                        jako každá jiná.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-light text-black rounded-4 my-4 text-center\">\r\n    <div class=\"container py-4\">\r\n        <h1 class=\"display-5 fw-bold text-black mb-4\">Směna je užitečná</h1>\r\n        <div class=\"row justify-content-center\">\r\n            <div class=\"col-12 col-md-10 col-lg-8\">\r\n                <p class=\"lead mb-5\">\r\n                    Už od počátku věků si lidé vyměňují užitečné služby skrze peníze, zkrátka protože je to <strong>pro\r\n                        obě strany výhodné</strong> a mají z toho <strong>užitek</strong>.\r\n                </p>\r\n                <div class=\"d-grid gap-2 d-sm-flex justify-content-sm-center\">\r\n                    <a class=\"btn btn-info text-dark fw-bold btn-lg px-4 rounded-3 shadow-sm\"\r\n                        href=\"https://dobrodruzi.cz/rezervace/\">\r\n                        Objednat průvodce\r\n                    </a>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-4 justify-content-center text-start\">\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Nabízím profesionální služby pro děti</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Velkým dobrodruhům pomáhám uskutečnit náročné expedice, naopak mladším rád uspořádám dobrodružný\r\n                        výlet na míru. V nabídce mám nejrůznější kurzy, během roku pořádám různorodé kroužky.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-md-5 rounded-4 shadow-sm\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-hand-sparkles fs-4\"></i>\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-3\">Tvořím pro děti příležitosti k osobnímu rozvoji</h4>\r\n                    <p class=\"fw-light mb-0\" \">\r\n                        Činnost pro děti tvořím tam, kde je o to zájem, proto mne neváhejte kontaktovat. Mohu stvořit\r\n                        kroužek pro Vaše mladé dobrodruhy <strong>i v místě Vašeho bydliště</strong>.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n    </div>\r\n</section>', 1, '2026-06-13 13:36:50', '2026-06-13 13:36:50'),
(204, 22, 'Sebeřízené vzdělávání', 'home', '[hlavicka typ=\"hero_default\" title1=\"Putujeme přírodou a učíme se novým dovednostem\" text1=\"Provázím mladé dobrodruhy na cestách za poznáním\" img1=\"/img/slideohen.jpg\" title2=\"Nabízím zážitky na celý život\" text2=\"výlety I expedice I vzdělávací kurzy\" img2=\"/img/slidelod.jpg\" title3=\"Vytvářím pro děti příležitosti k seberozvoji\" text3=\"A trávíme čas ve zdravém prostředí\" img3=\"/img/slidealex.jpg\"]\r\n\r\n[blok typ=\"blok_nadpis1\" podnadpis=\"Dobrodruzi.cz\" nadpis=\"Sebeřízené vzdělávání\" text=\"Vytvářím pro děti z Jindřichovic pod Smrkem <strong>příležitosti</strong> k všestrannému rozvoji, pořádám výlety, expedice, kurzy, kroužky, věnujeme se vzdělávání, praktickým dovednostem, a dalším volnočasovým aktivitám a hrám.\"]\r\n\r\n[blok typ=\"blok_uvod\" nadpis=\"Putujeme přírodou a učíme se novým dovednostem\" text1=\"S dětmi zkoumám svět, bádáme, učíme se a hrajeme si, se staršími dobrodruhy společně plánujeme a uskutečňujeme velká dobrodružství.\" text2=\"Na cestách najdou vaše děti nové přátele a zažijí spoustu zábavy a dobrodružství.\" odkaz_url=\"https://dobrodruzi.cz/cs/stranka/vylety\" odkaz_ikona=\"fa-solid fa-person-hiking\" odkaz_text=\"Výlety do přírody\" obrazek_src=\"/img/obr5.jpg\" obrazek_alt=\"Děti putující přírodou\"]\r\n\r\n\r\n[blok typ=\"blok_nadpis2\" nadpis=\"Víc než jen zábava\" text=\"Na výletech a kurzech děti rozvíjejí sebedůvěru, samostatnost, férovost, spolupráci. Učí se žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.\"]\r\n\r\n\r\n[blok typ=\"blok_karty3\" ikona1=\"fa-solid fa-person-hiking\" nadpis1=\"Výlety\" text1=\"Cestovatelské a tábornické znalosti, dovednosti přežití. Zkušený průvodce, respektující přístup a spousta zábavy.\" ikona2=\"fa-solid fa-users\" nadpis2=\"Kroužky\" text2=\"Většinu času trávíme v pohybu, v přírodě, za každého počasí. Věnujeme se, pohybovým hrám a vzdělávacím činnostem.\" ikona3=\"fa-solid fa-campground\" nadpis3=\"Kurzy\" text3=\"Nabízím vzdělávací činnosti, výuku programování, sjíždění řek na nafukovacích kánojích, cestovatelské dovednosti a znalosti.\"]\r\n\r\n[blok typ=\"blok_knihy\" obrazek_src=\"/img/knihy.png\" obrazek_alt=\"Respektující literatura\" podnadpis=\"Knihy, ze kterých vycházím\" nadpis=\"Respekt, svoboda, zodpovědnost​\" text=\"Klíčem ke spokojenému životu jsou dobré mezilidské vztahy, ty představují zdroj většiny radostí i bolestí v lidském životě. Mladí dobrodruzi pěstují vztahy založené na vzájemném respektu a úctě.​\" tlacitko1_url=\"https://www.peoplecomm.cz/respektovat-a-byt-respektovan\" tlacitko1_text=\"Respektovat a být res.\" tlacitko2_url=\"https://www.peoplecomm.cz/kniha-summerhill\" tlacitko2_text=\"Demokratická škola\" tlacitko3_url=\"https://www.peoplecomm.cz/svoboda-uceni\" tlacitko3_text=\"​​Svoboda učení\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_nadpis3\" nadpis=\"Dávám možnost říct <span class=\'text-info\'>„ne“</span>\" text=\"Ve skupině vytváříme skutečné dohody, hledáme podstatu názorů a potřeb, následně společně tvoříme přijatelná řešení. Akceptuji volbu a přirozené následky.\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_karty2\" ikona1=\"fa-solid fa-arrows-alt\" nadpis1=\"Připravuji řízený program formou nabídky\" text1=\"Využívám <strong>vnitřní motivace</strong> dětí, aby se mohly věnovat věcem proto, že v nich vidí <strong>smysl</strong>, že je baví a že samy chtějí.\" ikona2=\"fa-solid fa-handshake-angle\" nadpis2=\"„Jsem pro děti parťák, nikoli diktátor“\" text2=\"Děti vedu k samostatnosti, přistupuji k nim individuálně a s <strong>respektem</strong>. Zajišťuji bezpečné a motivující prostředí, ve kterém se mohou všestranně rozvíjet. Dávám jim prostor pro volnou hru a svobodné učení.\"]\r\n\r\n\r\n\r\n[blok typ=\"blok_obrazky_texty\" podnadpis=\"Bezpečný rozvoj\" nadpis=\"Učíme se prostřednictvím přírody\" text_uvod=\"Volnočasové aktivity organizuji převážně v přírodě, protože pobyt venku a pohyb na čerstvém vzduchu podporuje zdraví a odolnost dětí. Děti poznávají okolí místa, kde žijí, osvojují si praktické cestovatelské dovednosti a učí se rozpoznat přirozená nebezpečí.\" obr1_src=\"/img/sm-b1.jpg\" obr1_alt=\"Děti v kolektivu\" text1=\"Děti se učí žít v kolektivu, konstruktivně řešit sociální situace a respektovat domluvená pravidla.\" obr2_src=\"/img/sm-b4.jpg\" obr2_alt=\"Kreativita dětí\" text2=\"Vytvářejí si pozitivní vztah sami k sobě, a neustále na sobě pracují. Podporujeme jejich kreativitu a zručnost.\" obr3_src=\"/img/sm-b2.jpg\" obr3_alt=\"Rituály a přátelství\" text3=\"Poznávají hodnotu přátelství a sdílení, prožívají společně rituály. Osvojují si správné řešení konfliktů a efektivní komunikaci.\"]\r\n\r\n\r\n\r\n\r\n[blok typ=\"blok_info_karty\" ikona1=\"fa-solid fa-map-location-dot\" nadpis1=\"Místa konání\" text1=\"Scházíme se v Jindřichovicích pod Smrkem, nejlepší učebna je sama příroda, v létě i v zimě využíváme zázemí <a href=\'https://goo.gl/maps/itTNU4573LkMN6Jj7\' target=\'_blank\' class=\'text-info fw-semibold text-decoration-none\'>základny</a> Svobodům.\" odkaz1_url=\"https://goo.gl/maps/itTNU4573LkMN6Jj7\" odkaz1_text=\"Zobrazit mapu\" ikona2=\"fa-solid fa-calendar-days\" nadpis2=\"Termíny akcí\" text2=\"Na výlety vyrážíme o víkendech, kurzy a kroužky se konají ve všední dny.\" odkaz2_url=\"https://dobrodruzi.cz/rezervace/\" odkaz2_text=\"Zobrazit kalendář\" ikona3=\"fa-solid fa-hand-holding-heart\" nadpis3=\"Ceny\" text3=\"Dopravu, jídlo a ubytování na výletech si hradí děti sami (výdaje v řádu stokorun). Více informací najdete na stránce cen.\" odkaz3_url=\"https://dobrodruzi.cz/cs/stranka/cenik\" odkaz3_text=\"Přejít na Ceny\"]\r\n\r\n\r\n\r\n\r\n[blok typ=\"blok_kurzy_prog\" ikona=\"fa-solid fa-laptop-code\" nadpis=\"Nyní jsou nejžádanější kurzy programování\" text=\"Děti učím programovat, vytváříme počítačové hry, a trávíme čas ve zdravém prostředí.\" odkaz1_url=\"https://dobrodruzi.cz/cs/stranka/kurzy-programovani\" odkaz1_text=\"Více o kurzech »\" odkaz2_url=\"https://dobrodruzi.cz/rezervace/\" odkaz2_text=\"Volné termíny »\"]\r\n\r\n\r\n [blok typ=\"blok_kurzy_prog_detail\" badge=\"Technika venku\" title=\"Píšeme programátorský kód přímo v přírodě\" text=\"Kdo říká, že technologie patří jen do tmavých pokojů? Naše expedice kombinují pobyt na čerstvém vzduchu s rozvojem logického myšlení.\" img=\"/img/uploads/41/b20.jpg\" list1=\"Respektující přístup a práce vlastním tempem\" list2=\"Spojení moderních technologií a pobytu venku\" list3=\"Řešení reálných technických problémů\" btn_text=\"Prohlédnout aktivity\" btn_link=\"/aktivity\"]', 1, '2026-06-14 06:43:35', '2026-06-14 06:43:35');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(205, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní školka pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-19 14:58:29', '2026-06-19 14:58:29');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(206, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-19 15:02:08', '2026-06-19 15:02:08');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(207, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy (4 až 8 let), kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-19 15:05:42', '2026-06-19 15:05:42');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(208, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy (4 až 8 let), kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-19 15:07:01', '2026-06-19 15:07:01');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(209, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy (4 až 8 let), kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-19 15:10:30', '2026-06-19 15:10:30');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(210, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy (4 až 8 let), kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            \r\n            \r\n            <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\n            \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-19 15:12:00', '2026-06-19 15:12:00');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(211, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy (4 až 8 let), kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            \r\n  \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Pondělí - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-20 02:50:51', '2026-06-20 02:50:51');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(212, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            \r\n  \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">250\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Středa - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-27 01:05:18', '2026-06-27 01:05:18');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(213, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            \r\n  \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">150\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">2 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Středa - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-27 01:20:53', '2026-06-27 01:20:53');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(214, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            \r\n  \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">150\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>6\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Středa - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-27 01:22:32', '2026-06-27 01:22:32');
INSERT INTO `page_histories` (`id`, `page_id`, `title`, `slug`, `content`, `published`, `created_at`, `updated_at`) VALUES
(215, 25, 'Lesní školka', 'lesni-skolka', '[hlavicka typ=\"hero\" badge=\"Hlídání dětí · Jindřichovice pod Smrkem\" title1=\"Běháme bosky,\" title2=\"skáčeme do kaluží.\" text=\"Lesní družina pro malé dobrodruhy, kde příroda je učebnou, průvodce parťákem a svoboda základní kamen sebeřízeného vzdělávání.\" img=\"https://rezervace.dobrodruzi.cz/images/klucina.jpg\"]\r\n\r\n\r\n<!-- Podpora pro rodiče i děti -->\r\n<section class=\"py-5\" id=\"pro-rodice\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Zázemí a podpora\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mt-2\">Podpora pro rodiče i děti</h2>\r\n            <p class=\"lead text-muted\">Společný prostor, kde získáte čas pro sebe a Vaše děti bezpečné místo pro\r\n                svobodný růst.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-mug-hot fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Čas pro práci i odpočinek</h5>\r\n                    <p class=\"fw-light mb-0\">Potřebujete chvíli pro soustředění na práci, nebo zasloužený relax, ale\r\n                        chcete mít své dítě nablízku? Můžete v klidu pracovat, odpočívat nebo jen na chvíli zpomalit s\r\n                        vědomím, že je o děti postaráno.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-seedling fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Sebeřízené učení a hra</h5>\r\n                    <p class=\"fw-light mb-0\">Chcete aby Vaše děti měli prostor pro objevování, volnou hru a možnost\r\n                        učit se zcela svobodně? Příroda se stává naší učebnou, kde přirozená zvídavost udává\r\n                        směr.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-4\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 rounded-4 text-center\">\r\n                    <div class=\"d-flex align-items-center justify-content-center bg-white text-info rounded-circle mx-auto mb-4 shadow-sm\"\r\n                        style=\"width: 60px; height: 60px;\">\r\n                        <i class=\"fa-solid fa-handshake-angle fs-4\"></i>\r\n                    </div>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Respektující parťák</h5>\r\n                    <p class=\"fw-light mb-0\">Nabízím dětem bezpečné prostředí a průvodce při ruce, který plně rozumí\r\n                        respektující komunikaci i principům sebeřízeného vzdělávání. Pro děti nejsem autoritou, ale\r\n                        parťákem na jejich cestě.</p>\r\n                </div>\r\n            </div>\r\n            \r\n            \r\n  \r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n\r\n\r\n\r\n<!-- Základna a prostředí -->\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"zakladna\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě v Jindřichovicích pod Smrkem 213, který nabízí obří\r\n                    zahradu, hernu i les.\r\n                </p>\r\n\r\n                <p class=\"text-muted mb-4\">\r\n                    Žijí tu dvě spřátelené rodiny, takže tu děti občas mohou najít parťáky ke hře. A zatímco vy můžete v\r\n                    klidu pracovat ve sdílených prostorech domu, my se s dětmi můžeme vrhnout do průzkumu okolí.\r\n                </p>\r\n\r\n                <div class=\"row g-3 pt-2\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-tree fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Obří zahrada a les</span>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"d-flex align-items-center\">\r\n                            <div class=\"text-info me-3\"><i class=\"fa-solid fa-laptop-house fs-5\"></i></div>\r\n                            <span class=\"text-dark fw-medium small\">Sdílený pracovní prostor</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-lg border border-info border-opacity-10\">\r\n                    <img src=\"https://rezervace.dobrodruzi.cz/images/house.jpg\"\r\n                        alt=\"Dron pohled na dům Svobodného přístavu\" class=\"img-fluid rounded-4 w-100 shadow-sm\"\r\n                        style=\"object-fit: cover; max-height: 400px;\">\r\n\r\n                    <div class=\"position-absolute bottom-0 start-0 m-4 bg-dark bg-opacity-75 text-white px-3 py-2 rounded-3 small backdrop-blur\"\r\n                        style=\"backdrop-filter: blur(4px);\">\r\n                        <i class=\"fa-solid fa-compass me-2 text-info\"></i>Jindřichovice pod Smrkem 213\r\n                    </div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n\r\n<!-- Ceník -->\r\n<section class=\"py-5 bg-white\" id=\"cenik\">\r\n    <div class=\"container py-4\">\r\n\r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Investice do dětí\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark mb-3\">Zvolte si model hlídání</h2>\r\n            <p class=\"lead text-muted\">Zajišťuji bezpečné, komorní a rodinné prostředí. Vyberte si variantu, která\r\n                nejlépe vyhovuje časovým potřebám Vaší rodiny.</p>\r\n        </div>\r\n\r\n        <div class=\"row justify-content-center g-4 mb-5\">\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div class=\"card h-100 border-0 bg-light p-4 p-lg-5 rounded-4 shadow-sm text-center d-flex flex-column\">\r\n                    <div class=\"text-uppercase tracking-wider text-muted fw-bold small mb-3\">Občasná výpomoc</div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Individuální hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-dark d-block\" style=\"letter-spacing: -1px;\">150\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\">za hodinu péče</span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Ideální pro rodiče, kteří potřebují pohlídat dítě jen\r\n                        nepravidelně, na pár hodin nebo při nečekaných situacích.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-muted small\" style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Flexibilní domluva času</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-info me-2\"></i> Účtování odpracovaných hodin\r\n                        </li>\r\n                        <li><i class=\"fa-solid fa-check text-info me-2\"></i> Začlenění do denního programu</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-5\">\r\n                <div\r\n                    class=\"card h-100 border-0 bg-white p-4 p-lg-5 rounded-4 shadow-lg border-top border-info border-4 text-center d-flex flex-column position-relative\">\r\n                    <div\r\n                        class=\"position-absolute top-0 start-50 translate-middle badge bg-info text-dark rounded-pill px-3 py-2 shadow-sm fw-bold\">\r\n                        středa - čtvrtek</div>\r\n\r\n                    <div class=\"text-uppercase tracking-wider text-info fw-bold small mb-3 mt-2\">Pravidelná docházka\r\n                    </div>\r\n                    <h4 class=\"fw-bold text-dark mb-4\">Lesní skupinové hlídání</h4>\r\n\r\n                    <div class=\"mb-4\">\r\n                        <strong class=\"display-4 fw-bold text-info d-block\" style=\"letter-spacing: -1px;\">3 000\r\n                            Kč</strong>\r\n                        <span class=\"text-muted small fw-medium\"><strong>měsíční paušál</strong></span>\r\n                    </div>\r\n\r\n                    <p class=\"text-muted small mb-4 flex-grow-1\">Zajistěte svému dítěti stabilní režim, hluboké vztahy v\r\n                        komorní skupině a neustálý prostor pro jedinečný rozvoj.</p>\r\n\r\n                    <ul class=\"list-unstyled text-start mx-auto mb-0 text-dark small fw-medium\"\r\n                        style=\"max-width: 260px;\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>2 dny</strong> v\r\n                            týdnu</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong> až 10 hodin</strong>\r\n                            denně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> <strong>až 50 hodin</strong>\r\n                            měsíčně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i> Max. <strong>5\r\n                                dětí</strong> ve skupině</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i> Intenzivní individuální přístup</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n<section class=\"py-5 bg-light border-top border-bottom\" id=\"pruvodce\">\r\n    <div class=\"container py-3\">\r\n        \r\n        <div class=\"row g-5 align-items-center mb-5\">\r\n            \r\n            <div class=\"col-lg-5\">\r\n                <div class=\"position-relative p-2 bg-light rounded-4 shadow-sm border border-secondary border-opacity-10 text-center\">\r\n                    <img src=\"https://dobrodruzi.cz/img/ag1.jpg\" alt=\"Petr Lízal (AG) — průvodce\"\r\n                        class=\"img-fluid rounded-4 shadow-sm w-100\" style=\"object-fit: cover; max-height: 500px;\">\r\n                    \r\n                    <div class=\"position-absolute bottom-0 start-50 translate-middle-x mb-4 bg-dark bg-opacity-75 text-white px-4 py-2 rounded-pill small backdrop-blur shadow\" style=\"backdrop-filter: blur(4px); width: max-content;\">\r\n                        <span class=\"fw-bold\">Petr Lízal</span> (AG — Ejdží) · 37 let\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-lg-7 text-start\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Průvodce dětí\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n                \r\n                <h2 class=\"display-5 fw-bold text-dark mb-3\">„Jsem pro děti parťák, nikoli diktátor.\"</h2>\r\n\r\n                <div class=\"d-flex flex-wrap gap-2 mb-4\">\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-tree me-1\"></i> Průvodce</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-compass me-1\"></i> Lektor</span>\r\n                    <span class=\"badge bg-info text-white px-3 py-2 rounded-pill small fw-medium\"><i class=\"fa-solid fa-earth-americas me-1\"></i> Cestovatel</span>\r\n                </div>\r\n\r\n                <div>\r\n                    <p class=\"mb-3\">Odmala miluji dobrodružství a cestování, které mě naučilo odvaze. Jednoho dne jsem se s touhou po dobrodružství rozhodl opustit známé břehy a vydal se do neznámých hlubin Jižní Ameriky. Žil jsem několik měsíců v nejchudší čtvrti Paraguaye a právě tam se ze mě stal skutečný dobrodruh. Kromě cestování mě baví lezení po skalách, sjíždění řek, stejně jako svět technologií a programování.</p>\r\n\r\n                    <p class=\"mb-3\">Už více než dvacet let jsem průvodcem a lektorem pro děti. Organizoval jsem stovky výletů, několik expedic do zahraničí a desítky skautských táborů.</p>\r\n\r\n                    <p class=\"mb-0\">Pracoval jsem také ve svobodné škole, ale ještě mnoho let předtím mě postupně ovlivnily knihy jako Respektovat a být respektován, Nenásilná komunikace, Summerhill nebo Svoboda učení. Díky těmto knihám jsem pochopil, že děti nepotřebují autoritu nad sebou, ale bezpečný prostor, důvěru a parťáky.</p>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n        <div class=\"row g-4 pt-1 border-secondary border-opacity-10 text-start\">\r\n            \r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-graduation-cap fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>20+ let praxe</strong> s dětskými kolektivy, vedením zájmových kroužků a výletů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-campground fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Desítky zorganizovaných</strong> skautských táborů, víkendových setkání a outdoorových kurzů.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-school fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Zkušenost ze</strong> svobodné školy zaměřené na sebeřízené vzdělávání dětí.</span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n    </div>\r\n</section>\r\n\r\n\r\n\r\n<!-- Filozofie a přístup -->\r\n<section class=\"py-5 bg-white\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"row g-5 align-items-center\">\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Moje filozofie\r\n                </div>\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\">Proč Malí Dobrodruzi?</h2>\r\n                <div class=\"bg-white border-0 lead p-4 mb-4 rounded-4 border-start border-info border-4\">\r\n                    <i class=\"fa-solid fa-quote-left me-2\"></i> Nejdůležitější je pro mě celková atmosféra - místo, kde\r\n                    děti mohou být samy sebou, svobodně objevovat svět, zašpinit se od hlavy až k patě od bláta a cítit,\r\n                    že jsou přijímány takové, jaké jsou. Bez nátlaku, bez manipulace a bez plánů narýsovaných shora. Jen\r\n                    s hlubokým respektem, důvěrou a ryzí lidskostí.\r\n                    \r\n                </div>\r\n\r\n            </div>\r\n            <div class=\"col-lg-6\">\r\n                <div class=\"row g-4\">\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-tree text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Příroda jako učebna</h5>\r\n                            <p class=\"mb-0\">Les a louka jsou ideálním prostředím pro dětské hry a\r\n                                sebe-rozvoj bez omezení čtyřmi stěnami.</p>\r\n                        </div>\r\n                    </div>\r\n                    <div class=\"col-sm-6\">\r\n                        <div class=\"card card-body bg-light border-0 p-4 h-100 rounded-4\">\r\n                            <i class=\"fa-solid fa-user-group text-info fs-3 mb-3\"></i>\r\n                            <h5 class=\"fw-bold text-dark\">Respektující průvodce</h5>\r\n                            <p class=\"mb-0\">Jsem pro děti parťák, nikoli diktátor. Přistupuji k nim\r\n                                individuálně, s respektem a nenásilnou komunikací.</p>\r\n\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        <div class=\"row g-4 pt-0 border-secondary border-opacity-10 text-start\">\r\n            \r\n    \r\n            <div class=\"col-md-6 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-earth-americas fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>Expediční zkušenosti</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-12 col-lg-6\">\r\n                <div class=\"d-flex align-items-start h-100 p-3 bg-light rounded-4\">\r\n                    <div class=\"bg-white text-info rounded-circle d-flex align-items-center justify-content-center shadow-sm p-3 me-3 flex-shrink-0\" style=\"width: 50px; height: 50px;\">\r\n                        <i class=\"fa-solid fa-book-open fs-5\"></i>\r\n                    </div>\r\n                    <div>\r\n                        <span class=\"text-dark small\"><strong>NVC - Nenásilná komunikace</strong></span>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n        </div>\r\n\r\n\r\n        </div>\r\n    </div>\r\n</section>\r\n\r\n<!-- Provoz a denní režim -->\r\n<section class=\"py-5 bg-light border-top\">\r\n    <div class=\"container py-3\">\r\n        <div class=\"text-center mb-5\">\r\n            <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                Provoz a denní režim\r\n                <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n            </div>\r\n            <h2 class=\"display-5 fw-bold text-dark\">Praktické informace</h2>\r\n            <p class=\"lead text-muted\">Většinu času trávíme venku za každého počasí. Říká se, že neexistuje špatné počasí, jen špatné oblečení.</p>\r\n        </div>\r\n\r\n        <div class=\"row g-4 justify-content-center\">\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-clock text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Otevírací doba</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><strong>Středa - Čtvrtek:</strong> 4:30 – 22:00</li>\r\n                        <li class=\"mb-2\"><strong>Okno pro předání dětí:</strong>\r\n                            <ul>\r\n                            <li>04:30 – 9:00</li>\r\n                            <li>14:30 – 15:30</li>\r\n                            <li>18:00 – 22:00</li>\r\n                            </ul>\r\n                          </li>\r\n                    </ul>\r\n                    <p class=\"text-muted small mt-3 fst-italic\">Individuální domluva na dřívějším příchodu nebo\r\n                        pozdějším odchodu je možná po předchozí dohodě.</p>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-shirt text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Vybavení dítěte</h5>\r\n                    <ul class=\"list-unstyled text-muted small mb-0\">\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Batůžek na denní nošení</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Náhradní oblečení na\r\n                            základně</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Funkční vrstvy (merino,\r\n                            gore-tex)</li>\r\n                        <li class=\"mb-2\"><i class=\"fa-solid fa-check text-success me-2\"></i>Jídlo a pití z domova</li>\r\n                        <li><i class=\"fa-solid fa-check text-success me-2\"></i>Vše řádně podepsané</li>\r\n                    </ul>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"col-md-6 col-lg-4\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-phone-volume text-info fs-3 mb-3\"></i>\r\n                    <h5 class=\"fw-bold text-dark mb-3\">Dostupnost rodičů</h5>\r\n                    <p class=\"text-muted small mb-0\">Rodiče mustí být v době docházky vždy na telefonu pro případ pláče\r\n                        či úrazu. Bezpečnost dětí je naší prioritou, ať už jste s námi na základně nebo doma.</p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"text-start mt-5 mb-4\">\r\n            <h4 class=\"fw-bold text-dark h5 text-uppercase tracking-wider opacity-75\">Podmínky a zázemí fungování</h4>\r\n        </div>\r\n\r\n        <div class=\"row g-4\">\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-user-check text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Věk od 4 let</h6>\r\n                    <p class=\"text-muted small mb-0\">Dítě zvládá odloučení od rodičů, komunikuje a akceptuje společná\r\n                        pravidla.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-sun text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Celoroční provoz</h6>\r\n                    <p class=\"text-muted small mb-0\">Jsme venku za každého počasí. Déšť ani sníh nás nezastaví, učíme se\r\n                        odolnosti.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-users-gear text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Kapacita 6 dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">Zaručujeme maximální individuální přístup a bezpečí pro každého.</p>\r\n                </div>\r\n            </div>\r\n            <div class=\"col-sm-6 col-lg-3\">\r\n                <div class=\"card h-100 border-0 shadow-sm rounded-4 p-4\">\r\n                    <i class=\"fa-solid fa-apple-whole text-info fs-3 mb-3\"></i>\r\n                    <h6 class=\"fw-bold text-dark mb-3\">Stravování dětí</h6>\r\n                    <p class=\"text-muted small mb-0\">\r\n                        Obědváme v teplé jídelně na základně, ohřev jídla možný v mikrovlnné troubě.\r\n                    </p>\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n    </div>\r\n</section>', 1, '2026-06-27 01:22:58', '2026-06-27 01:22:58'),
(216, 18, 'Kontakt', 'kontakt', '[hlavicka typ=\"hero\" badge=\"Lesní klub\" title1=\"Děti do lesa,\" title2=\"rodičům relax.\" text=\"Nabízím úžasný program pro Vaše mladé dobrodruhy.\" img=\"/img/uploads/42/b21.jpg\"]\r\n\r\n\r\n\r\n\r\n<section class=\"py-2\" id=\"zakladna\">\r\n    <div class=\"container py-4\">\r\n        \r\n      \r\n        \r\n        <div class=\"text-center mb-5 mx-auto\" style=\"max-width: 700px;\">\r\n            <h2 class=\"display-6 fw-bold text-dark mb-3\">Místo kde se scházíme</h2>\r\n            <p class=\"lead text-muted mb-0\">\r\n                Zobrazit na mapě \r\n                <a href=\"https://maps.app.goo.gl/8utGAo7Z5CKujB2c8\" target=\"_blank\" rel=\"noopener\" class=\"text-info fw-medium text-decoration-none\">\r\n                    základnu kde se scházíme <i class=\"fa-solid fa-arrow-up-right-from-square ms-1\" style=\"font-size: 0.85em;\"></i>\r\n                </a>\r\n            </p>\r\n        </div>\r\n\r\n        \r\n        \r\n        \r\n        <div class=\"row g-5 align-items-center\">\r\n            \r\n            <div class=\"col-lg-6\">\r\n                \r\n                <div class=\"text-info small text-uppercase tracking-wider fw-bold mb-2\">\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 me-2\" style=\"width: 24px;\">\r\n                    Základna klubu\r\n                    <hr class=\"d-inline-block border-info border-1 opacity-50 mb-1 ms-2\" style=\"width: 24px;\">\r\n                </div>\r\n\r\n                <h2 class=\"display-5 fw-bold text-dark mb-4\" style=\"line-height: 1.2; letter-spacing: -0.5px;\">\r\n                    Dům uprostřed <span class=\"text-info fst-italic\">přírody</span>\r\n                </h2>\r\n\r\n                <p class=\"lead text-muted mb-4 lh-base\" style=\"font-size: 1.15rem;\">\r\n                    Naši Malí Dobrodruzi kotví ve Svobodném přístavě, který nabízí obří zahradu, hernu i bezprostřední přístup do l